window.VARC_FINAL = {"version":1,"papers":[{"id":"fs-qa-1","sec":"qa","title":"Final Stretch · Quant paper 1","minutes":40,"qids":["fs-q1-1","fs-q1-2","fs-q1-3","fs-q1-4","fs-q1-5","fs-q1-6","fs-q1-7","fs-q1-8","fs-q1-9","fs-q1-10","fs-q1-11","fs-q1-12","fs-q1-13","fs-q1-14","fs-q1-15","fs-q1-16","fs-q1-17","fs-q1-18","fs-q1-19","fs-q1-20","fs-q1-21","fs-q1-22"]},{"id":"fs-qa-2","sec":"qa","title":"Final Stretch · Quant paper 2","minutes":40,"qids":["fs-q2-1","fs-q2-2","fs-q2-3","fs-q2-4","fs-q2-5","fs-q2-6","fs-q2-7","fs-q2-8","fs-q2-9","fs-q2-10","fs-q2-11","fs-q2-12","fs-q2-13","fs-q2-14","fs-q2-15","fs-q2-16","fs-q2-17","fs-q2-18","fs-q2-19","fs-q2-20","fs-q2-21","fs-q2-22"]},{"id":"fs-qa-3","sec":"qa","title":"Final Stretch · Quant paper 3","minutes":40,"qids":["fs-q3-1","fs-q3-2","fs-q3-3","fs-q3-4","fs-q3-5","fs-q3-6","fs-q3-7","fs-q3-8","fs-q3-9","fs-q3-10","fs-q3-11","fs-q3-12","fs-q3-13","fs-q3-14","fs-q3-15","fs-q3-16","fs-q3-17","fs-q3-18","fs-q3-19","fs-q3-20","fs-q3-21","fs-q3-22"]},{"id":"fs-qa-4","sec":"qa","title":"Final Stretch · Quant paper 4","minutes":40,"qids":["fs-q4-1","fs-q4-2","fs-q4-3","fs-q4-4","fs-q4-5","fs-q4-6","fs-q4-7","fs-q4-8","fs-q4-9","fs-q4-10","fs-q4-11","fs-q4-12","fs-q4-13","fs-q4-14","fs-q4-15","fs-q4-16","fs-q4-17","fs-q4-18","fs-q4-19","fs-q4-20","fs-q4-21","fs-q4-22"]},{"id":"fs-dilr-1","sec":"dilr","title":"Final Stretch · DILR paper 1","minutes":40,"qids":["fs-d1-1-1","fs-d1-1-2","fs-d1-1-3","fs-d1-1-4","fs-d1-1-5","fs-d1-2-1","fs-d1-2-2","fs-d1-2-3","fs-d1-2-4","fs-d1-3-1","fs-d1-3-2","fs-d1-3-3","fs-d1-3-4","fs-d1-4-1","fs-d1-4-2","fs-d1-4-3","fs-d1-4-4","fs-d1-5-1","fs-d1-5-2","fs-d1-5-3","fs-d1-5-4","fs-d1-5-5"],"tita":11},{"id":"fs-dilr-2","sec":"dilr","title":"Final Stretch · DILR paper 2","minutes":40,"qids":["fs-d2-1-1","fs-d2-1-2","fs-d2-1-3","fs-d2-1-4","fs-d2-1-5","fs-d2-2-1","fs-d2-2-2","fs-d2-2-3","fs-d2-2-4","fs-d2-3-1","fs-d2-3-2","fs-d2-3-3","fs-d2-3-4","fs-d2-4-1","fs-d2-4-2","fs-d2-4-3","fs-d2-4-4","fs-d2-5-1","fs-d2-5-2","fs-d2-5-3","fs-d2-5-4","fs-d2-5-5"],"tita":12},{"id":"fs-dilr-3","sec":"dilr","title":"Final Stretch · DILR paper 3","minutes":40,"qids":["fs-d3-1-1","fs-d3-1-2","fs-d3-1-3","fs-d3-1-4","fs-d3-1-5","fs-d3-2-1","fs-d3-2-2","fs-d3-2-3","fs-d3-2-4","fs-d3-3-1","fs-d3-3-2","fs-d3-3-3","fs-d3-3-4","fs-d3-4-1","fs-d3-4-2","fs-d3-4-3","fs-d3-4-4","fs-d3-5-1","fs-d3-5-2","fs-d3-5-3","fs-d3-5-4","fs-d3-5-5"],"tita":11},{"id":"fs-dilr-4","sec":"dilr","title":"Final Stretch · DILR paper 4","minutes":40,"qids":["fs-d4-1-1","fs-d4-1-2","fs-d4-1-3","fs-d4-1-4","fs-d4-2-1","fs-d4-2-2","fs-d4-2-3","fs-d4-2-4","fs-d4-2-5","fs-d4-3-1","fs-d4-3-2","fs-d4-3-3","fs-d4-3-4","fs-d4-4-1","fs-d4-4-2","fs-d4-4-3","fs-d4-4-4","fs-d4-5-1","fs-d4-5-2","fs-d4-5-3","fs-d4-5-4","fs-d4-5-5"],"tita":10},{"id":"fs-varc-1","sec":"varc","title":"Final Stretch · VARC paper 1","minutes":40,"qids":["fs-v1-1-1","fs-v1-1-2","fs-v1-1-3","fs-v1-1-4","fs-v1-2-1","fs-v1-2-2","fs-v1-2-3","fs-v1-2-4","fs-v1-3-1","fs-v1-3-2","fs-v1-3-3","fs-v1-3-4","fs-v1-4-1","fs-v1-4-2","fs-v1-4-3","fs-v1-4-4","fs-v1-5","fs-v1-6","fs-v1-7","fs-v1-8","fs-v1-9","fs-v1-10","fs-v1-11","fs-v1-12"]},{"id":"fs-varc-2","sec":"varc","title":"Final Stretch · VARC paper 2","minutes":40,"qids":["fs-v2-1-1","fs-v2-1-2","fs-v2-1-3","fs-v2-1-4","fs-v2-2-1","fs-v2-2-2","fs-v2-2-3","fs-v2-2-4","fs-v2-3-1","fs-v2-3-2","fs-v2-3-3","fs-v2-3-4","fs-v2-4-1","fs-v2-4-2","fs-v2-4-3","fs-v2-4-4","fs-v2-5","fs-v2-6","fs-v2-7","fs-v2-8","fs-v2-9","fs-v2-10","fs-v2-11","fs-v2-12"]},{"id":"fs-varc-3","sec":"varc","title":"Final Stretch · VARC paper 3","minutes":40,"qids":["fs-v3-1-1","fs-v3-1-2","fs-v3-1-3","fs-v3-1-4","fs-v3-2-1","fs-v3-2-2","fs-v3-2-3","fs-v3-2-4","fs-v3-3-1","fs-v3-3-2","fs-v3-3-3","fs-v3-3-4","fs-v3-4-1","fs-v3-4-2","fs-v3-4-3","fs-v3-4-4","fs-v3-5","fs-v3-6","fs-v3-7","fs-v3-8","fs-v3-9","fs-v3-10","fs-v3-11","fs-v3-12"]},{"id":"fs-varc-4","sec":"varc","title":"Final Stretch · VARC paper 4","minutes":40,"qids":["fs-v4-1-1","fs-v4-1-2","fs-v4-1-3","fs-v4-1-4","fs-v4-2-1","fs-v4-2-2","fs-v4-2-3","fs-v4-2-4","fs-v4-3-1","fs-v4-3-2","fs-v4-3-3","fs-v4-3-4","fs-v4-4-1","fs-v4-4-2","fs-v4-4-3","fs-v4-4-4","fs-v4-5","fs-v4-6","fs-v4-7","fs-v4-8","fs-v4-9","fs-v4-10","fs-v4-11","fs-v4-12"]}],"passages":{"fs-d1-s1":{"title":"Five cafés, one quarter","paras":["A café chain has five outlets, A to E. The first table gives the number of customers (in hundreds) each outlet served in January, February and March. The second gives the average bill per customer (₹) in the same months.","Revenue of an outlet in a month = number of customers × average bill.",{"table":{"head":["Outlet","Jan","Feb","Mar"],"rows":[["A","40","44","50"],["B","55","50","60"],["C","30","36","33"],["D","62","58","70"],["E","25","30","40"]]},"caption":"Customers (hundreds)"},{"table":{"head":["Outlet","Jan","Feb","Mar"],"rows":[["A","250","240","230"],["B","200","220","210"],["C","320","300","310"],["D","180","190","175"],["E","280","270","260"]]},"caption":"Average bill (₹)"}],"difficulty":"easy","kind":"set","family":"Read the data"},"fs-d1-s2":{"title":"Eight talks, four days","paras":["Eight speakers, A to H, give one talk each at a conference that runs from Monday to Thursday. Each day has a morning slot and an afternoon slot, and each slot has exactly one talk.","1. A speaks on Tuesday.\n2. B and C speak on the same day, C before B.\n3. D speaks in the slot immediately after E's slot.\n4. E speaks in a morning slot, but not on Monday.\n5. F speaks on an earlier day than G, and G speaks in a morning slot.\n6. H speaks in an afternoon slot, on a later day than A."],"difficulty":"medium","kind":"set","family":"Fit people to slots"},"fs-d1-s3":{"title":"Five-team league","paras":["Five teams, P, Q, R, S and T, played a league in which every team played every other team exactly once. A win earned 3 points, a draw 1 point and a loss 0.","• P finished with 10 points and T with 1 point.\n• Exactly three matches were drawn, and P drew with S.\n• All five teams finished with different points, and Q finished above R, which finished above S.\n• R beat T."],"difficulty":"hard","kind":"set","family":"Scores and overlaps"},"fs-d1-s4":{"title":"Locker codes","paras":["A bank of nine lockers is arranged in a 3 × 3 grid. Each locker shows a different number from 1 to 9.","• The four corner lockers show the four even numbers.\n• The top row adds up to 13, and the middle row adds up to 17.\n• The left column adds up to 13.\n• The diagonal from the top-left corner to the bottom-right corner adds up to 15."],"difficulty":"medium","kind":"set","family":"Maps and grids"},"fs-d1-s5":{"title":"Pass and drop","paras":["Seven friends, numbered 1 to 7, sit in a circle in clockwise order. A ball starts with friend 1.","In round k (k = 1, 2, 3, …) the person holding the ball passes it k places clockwise, counting only friends still in the game. The friend who receives it is out and immediately hands the ball to the next friend still in the game, clockwise. The game ends when one friend is left, who wins."],"difficulty":"hard","kind":"set","family":"Follow the rules"},"fs-d2-s1":{"title":"Airline routes","paras":["An airline flies five routes. The table gives, for one week, the number of flights, seats per flight, the load factor (percentage of seats filled) and the average fare per passenger.","Passengers = flights × seats × load factor. Revenue = passengers × average fare.",{"table":{"head":["Route","Cities","Flights/week","Seats/flight","Load factor","Avg fare (₹)"],"rows":[["R1","Delhi–Mumbai","70","180","85%","5,200"],["R2","Delhi–Bengaluru","56","180","80%","6,100"],["R3","Mumbai–Chennai","42","150","90%","4,300"],["R4","Bengaluru–Kolkata","28","180","75%","6,800"],["R5","Chennai–Hyderabad","35","120","70%","3,200"]]}}],"difficulty":"easy","kind":"set","family":"Read the data"},"fs-d2-s2":{"title":"Night duty roster","paras":["Five doctors, A to E, each take night duty on exactly one day from Monday to Friday, one doctor a day. Each has a different speciality: cardiology, dermatology, ENT, neurology and orthopaedics.","1. E is on duty on Monday and is not the ENT specialist.\n2. The cardiologist is on duty on Wednesday; C is not the cardiologist.\n3. A is on duty the day after the dermatologist.\n4. B is the orthopaedist and is on duty on an earlier day than C.\n5. The neurologist is on duty on Friday, and D is not the neurologist."],"difficulty":"easy","kind":"set","family":"Fit people to slots"},"fs-d2-s3":{"title":"Two products, five days of ratings","paras":["Products X and Y each received exactly one customer rating per day for five days. Every rating was a whole number from 1 to 5. The table shows each product's average rating up to and including each day; a dash means the value is not given.",{"table":{"head":["Average up to","Day 1","Day 2","Day 3","Day 4","Day 5"],"rows":[["X","–","3.5","–","3.5","3.6"],["Y","–","–","3","3.25","–"]]}},"• On every day, X and Y received different ratings, and X's rating was higher than Y's on exactly three days.\n• X's day-1 rating was higher than Y's day-1 rating.\n• X's day-3 rating was lower than its day-4 rating.\n• Y's day-5 rating was higher than each of its earlier ratings, and Y's day-1 rating was lower than each of its later ratings."],"difficulty":"hard","kind":"set","family":"Scores and overlaps"},"fs-d2-s4":{"title":"Roads and tolls","paras":["Six towns, A to F, are linked by two-way roads. The table lists every road with its length and the toll charged on it (₹, one way). There are no other roads.",{"table":{"head":["Road","Length (km)","Toll (₹)"],"rows":[["A–B","40","0"],["A–C","25","50"],["B–D","30","0"],["C–D","35","0"],["C–E","60","0"],["D–E","20","30"],["D–F","55","0"],["E–F","25","40"],["B–F","90","0"]]}},"A route may not pass through the same town twice."],"difficulty":"medium","kind":"set","family":"Maps and grids"},"fs-d2-s5":{"title":"The richest one pays","paras":["Four friends, A, B, C and D, start a game with 13, 9, 5 and 3 coins respectively.","In each round, the friend with the most coins gives one coin to each of the other three. If two or more friends are tied for the most, the one who comes first alphabetically gives."],"difficulty":"medium","kind":"set","family":"Follow the rules"},"fs-d3-s1":{"title":"Electricity slabs","paras":["Five households are billed every quarter. The bill is a fixed charge of ₹150 plus an energy charge: ₹4 per unit for the first 100 units, ₹6 per unit for the next 200 units (units 101 to 300) and ₹8 per unit for every unit above 300.",{"table":{"head":["Household","Q1","Q2","Q3","Q4"],"rows":[["H1","250","320","410","280"],["H2","180","210","260","190"],["H3","90","120","150","95"],["H4","340","380","450","360"],["H5","300","310","290","305"]]},"caption":"Units consumed"}],"difficulty":"medium","kind":"set","family":"Read the data"},"fs-d3-s2":{"title":"Seven in a queue","paras":["Seven people, A to G, stand in a single queue at positions 1 (front) to 7 (back). Three are doctors, two are engineers and two are lawyers.","1. C stands at position 4, and D stands immediately behind C. D is an engineer.\n2. G, a doctor, stands at the back of the queue.\n3. A stands ahead of B with exactly two people between them.\n4. E stands somewhere ahead of F.\n5. The person at the front is a lawyer.\n6. No two doctors stand next to each other.\n7. Both engineers stand behind A."],"difficulty":"easy","kind":"set","family":"Fit people to slots"},"fs-d3-s3":{"title":"Three tests, four students","paras":["Four students, W, X, Y and Z, took three tests. In each test the four students scored 5, 6, 7 and 8 marks in some order (no ties).","• W scored 8 in Test 1, but W's total was lower than every other student's total.\n• X's total was 22.\n• Y scored the same marks in Test 2 and Test 3.\n• Z scored more in Test 3 than in Test 1."],"difficulty":"medium","kind":"set","family":"Scores and overlaps"},"fs-d3-s4":{"title":"Who lives where","paras":["Eight families, A to H, live in a four-storey building. Each floor (1 is the lowest, 4 the top) has a West flat and an East flat, and each family has one flat.","1. A lives directly above B (same side, one floor up), in a West flat.\n2. C lives in the East flat on the top floor.\n3. D and E live on the same floor; D is in the West flat.\n4. F lives in an East flat on floor 1 or 2.\n5. G lives on a higher floor than H.\n6. H does not live in flat 1-West, and B does not live on floor 1."],"difficulty":"medium","kind":"set","family":"Maps and grids"},"fs-d3-s5":{"title":"The art auction","paras":["Four paintings, W, X, Y and Z, are auctioned one after another. Five bidders, P, Q, R, S and T, start with budgets (₹ lakh) of 80, 70, 75, 60 and 55. The table shows how much each bidder values each painting.",{"table":{"head":["Painting","P","Q","R","S","T"],"rows":[["W","45","50","40","35","30"],["X","60","55","70","40","50"],["Y","50","65","30","60","45"],["Z","75","40","35","50","55"]]},"caption":"Valuations (₹ lakh)"},"Rules for each painting: a bidder takes part only if their remaining budget is at least their valuation of that painting. The participant with the highest valuation wins and pays the second-highest valuation among the participants. The price is subtracted from the winner's budget. Unless stated otherwise, the order is W, X, Y, Z."],"difficulty":"hard","kind":"set","family":"Follow the rules"},"fs-d4-s1":{"title":"A trader's six stocks","paras":["A trader bought shares of six companies and later sold all of them. The table gives the number of shares and the buying and selling price per share (₹).",{"table":{"head":["Stock","Shares","Buy price (₹)","Sell price (₹)"],"rows":[["A","100","250","290"],["B","50","820","780"],["C","200","115","138"],["D","80","410","451"],["E","150","96","90"],["F","40","1,250","1,400"]]}},"Where brokerage applies, it is 0.5% of the value of every purchase and every sale."],"difficulty":"easy","kind":"set","family":"Read the data"},"fs-d4-s2":{"title":"Interns and teams","paras":["Six interns, A to F, are placed in three teams — Analytics, Design and Engineering — two interns per team. Two interns come from each of three colleges: IIT, NIT and BITS.","1. C is in Design and is from NIT.\n2. D and E are in the same team, which is not Analytics.\n3. F is from BITS and is not in Design.\n4. A and B are in different teams. B is from IIT, and A is not from NIT.\n5. The two Engineering interns are from different colleges, and so are the two Analytics interns."],"difficulty":"medium","kind":"set","family":"Fit people to slots"},"fs-d4-s3":{"title":"Three streaming apps","paras":["A survey asked 200 people which of three streaming apps — N, P and H — they use. 110 use N, 90 use P and 80 use H. 10 people use none of the three, and 40 people use exactly two of the three."],"difficulty":"hard","kind":"set","family":"Scores and overlaps"},"fs-d4-s4":{"title":"Sixteen plots","paras":["A farm is divided into a 4 × 4 grid of plots. Rows are numbered 1 to 4 from north to south and columns 1 to 4 from west to east; plot (2, 3) means row 2, column 3. Each plot grows one of four crops — wheat, rice, maize or pulses — and every row and every column has each crop exactly once.","• Plot (1, 1) grows wheat and plot (1, 4) grows pulses.\n• Plot (2, 3) grows rice.\n• No plot on the diagonal from (1, 1) to (4, 4) grows rice.\n• Plot (4, 4) grows maize or pulses."],"difficulty":"medium","kind":"set","family":"Maps and grids"},"fs-d4-s5":{"title":"Two counters","paras":["A bank opens two counters, 1 and 2, at 10:00. Eight customers arrive; the table gives each one's arrival time (minutes after 10:00) and how long their service takes.",{"table":{"head":["Customer","A","B","C","D","E","F","G","H"],"rows":[["Arrives at","0","1","2","4","5","9","10","12"],["Service (min)","6","4","5","3","7","2","4","3"]]}},"Rules: whenever a counter is free and someone is waiting, the next customer goes to it at once (counter 1 if both are free). D and G are senior citizens: whenever they are waiting, they are served before everyone else who is waiting. Otherwise customers are served in order of arrival. A service, once started, is never interrupted."],"difficulty":"hard","kind":"set","family":"Follow the rules"},"fs-v1-p1":{"title":"The quiet arithmetic of nudges","paras":["When governments discovered behavioural economics, they discovered a cheap instrument. A tax requires legislation and a subsidy requires money, but a change in the default option on a pension form requires only a printer. Enrolment in workplace savings schemes rose sharply wherever employees were enrolled automatically and allowed to opt out, rather than asked to opt in. The lesson seemed to be that people are not so much irrational as inert, and that a well-designed form could do the work once assigned to persuasion.","The enthusiasm that followed was understandable, and some of it was deserved. Yet the early results came from a narrow class of decisions: those taken once, on paper, by people who had no strong preference either way. Defaults work best precisely where people care least. When the decision matters to them, or when it must be repeated daily, the nudge tends to fade. A reminder to take medication improves adherence for a few weeks; a smaller plate reduces what is eaten at one meal but not, it seems, what is eaten in a week. Behaviour bends towards the nudge and then, quietly, bends back.","There is also a problem of arithmetic. A nudge that raises the rate of some desirable behaviour by two percentage points can be reported as a large proportional effect if the base rate was low, and studies with striking results are more likely to be published than those with none. When researchers later collected every trial run by two government ‘nudge units’, including the unpublished ones, the average effect was roughly a sixth of what the academic literature had suggested. The effects were real; they were simply small.","None of this makes nudges useless. A small effect that costs almost nothing can still be a bargain, and a default that adds a few per cent to retirement savings, compounded over decades, is not trivial. The danger lies elsewhere: in the temptation to treat the cheap instrument as a substitute for the expensive one. A government that nudges citizens to save while leaving wages stagnant, or that redesigns the menu while ignoring the price of fresh food, has mistaken a tool for adjusting choices at the margin for a policy that changes the conditions under which choices are made."],"difficulty":"medium"},"fs-v1-p2":{"title":"Mining the abyss","paras":["The deep seabed, four to six kilometres down, is strewn in places with potato-sized nodules rich in manganese, nickel, cobalt and copper — metals that batteries for electric vehicles require in growing quantities. To mining companies the nodules look like the ideal ore: they lie loose on the surface, need no blasting and contain several valuable metals at once. To many marine biologists they look like something else: the only hard surface for hundreds of kilometres on an otherwise soft plain of mud, and therefore the anchor for most of the animals that live there.","Very little is known about those animals. Surveys of one nodule field in the Pacific found that the majority of the species collected had never been described, and that many were known from a single specimen. Life in the abyss runs slowly. Nodules themselves grow by a few millimetres every million years, and communities disturbed by test mining in the 1980s had still not recovered when scientists returned decades later. Removing the nodules removes the habitat on a timescale that, for practical purposes, is permanent.","Supporters of seabed mining reply that every source of metal has a cost. Mines on land clear forests, displace communities and leave behind toxic tailings; the deep sea, they argue, has no people to displace and no forests to clear. If the world needs these metals to decarbonise, the question is not whether to damage some ecosystem but which one.","The argument is serious, but it assumes that demand is fixed. Battery chemistries are changing quickly, and several now in commercial use need no cobalt or nickel at all. Recycling, too, could supply a growing share of demand as the first generation of electric cars reaches the scrapyard. The case for opening a new frontier of extraction is therefore weakest exactly where it claims to be strongest: in the confident forecast of what the world will need in twenty years."],"difficulty":"easy"},"fs-v1-p3":{"title":"The forger's question","paras":["In 1945 the Dutch painter Han van Meegeren, accused of having sold a national treasure — a Vermeer — to Hermann Göring, defended himself by proving that the painting was not a Vermeer at all. He had painted it himself, and to demonstrate the point he painted another in front of witnesses. The charge of collaboration collapsed into a charge of fraud, and the paintings that critics had praised as among Vermeer's finest were quietly taken off the walls.","The episode poses a question that is easy to state and hard to answer. If a painting is admired for its beauty, and the painting does not change, why should its value collapse when its authorship does? One answer, popular among aesthetic formalists, is that it should not: what matters is what is visible on the canvas, and the shock of discovery reveals only the snobbery of those who had praised a name. On this view the forgery exposes the critic, not the painting.","The formalist answer has the virtue of consistency, but it misdescribes what we admire in a work of art. A painting is not only an arrangement of pigments; it is also an achievement, and achievements are relative to their circumstances. To have solved, in the 1660s, the problem of rendering light falling through a window onto a wall is one thing; to imitate that solution three centuries later, once it is known to be possible, is another. The two canvases may look alike, but they are not answers to the same question. What the forgery lacks is not a visible property but a historical one, and historical properties are no less real for being invisible.","This does not mean that the forger's skill counts for nothing. Van Meegeren's paintings deceived experts, and deception of that order is itself an achievement, though not an artistic one of the kind the paintings claimed. It means only that the question ‘is it beautiful?’ and the question ‘what has been done here?’ are different questions, and that our responses to art have always depended on both. The scandal of a forgery lies in having the second question answered falsely."],"difficulty":"hard"},"fs-v1-p4":{"title":"The monsoon's merchants","paras":["Long before European ships entered the Indian Ocean, its trade ran on a timetable set by the wind. From roughly April to September the south-west monsoon carried ships from the coasts of Arabia and East Africa towards India; from November to February the north-east monsoon carried them back. A merchant who missed the season could wait months for the next one, and port cities grew up as places to wait as much as places to trade.","This rhythm shaped the communities that lived by it. Because voyages were long and returns slow, traders settled for months or years in foreign ports, married locally and formed diasporas — Gujaratis in East Africa, Arabs on the Malabar coast, Chinese in the ports of Southeast Asia. Credit travelled along these networks of kin and faith; a promissory note written in Cairo might be honoured in Aden or Calicut because the people at each end belonged to the same community. Trust, rather than any state, guaranteed the contracts.","Historians once described this world as a set of local trades waiting to be unified by Europeans. The Portuguese, arriving in 1498, certainly tried: they built forts, demanded passes from Asian ships and attempted to monopolise the trade in pepper. But their success was partial. Most of the ocean's commerce continued in Asian hands for another two centuries, often simply by avoiding Portuguese forts. What changed the ocean more decisively was not the cannon but the joint-stock company, which could raise capital from thousands of investors and wait for returns longer than any family firm.","The monsoon world was thus neither a timeless tradition nor a primitive stage of globalisation. It was a sophisticated system of exchange adapted to its constraints: seasonal winds, long distances, and the absence of any single authority over the sea. Its decline is a reminder that what displaces a system is not always the force that most visibly attacks it."],"difficulty":"medium"},"fs-v2-p1":{"title":"Who wrote this?","paras":["For most of history the question ‘who wrote this?’ had a simple answer, even when it was hard to discover. A text was the product of a mind, and the mind belonged to a person who could be praised, paid, sued or imprisoned for it. Copyright law, literary criticism and the ordinary ethics of plagiarism all rest on that assumption. Large language models unsettle it, not because they write well — many do not — but because they make it hard to say where a piece of writing came from.","Consider a report drafted by a model from a two-line prompt, then revised by a person who rewrites a third of it. The person chose the topic and approved the result; the model produced most of the sentences; and the model itself was shaped by millions of texts written by people who will never be credited. Each of the familiar candidates for authorship has a partial claim, and none has a complete one.","One response is to insist that authorship belongs to whoever takes responsibility. A newspaper editor does not write every headline, but answers for all of them. On this view the question is not who produced the words but who stands behind them, and the person who submits the report is its author whatever tools were used. The response has practical appeal: it tells institutions whom to hold accountable.","But responsibility and authorship have never been quite the same thing. We hold publishers responsible for what they print without calling them authors, and we credit authors for books they were too ill to defend. Authorship has also meant a claim to a certain kind of effort and originality — the claim that the work reflects a particular mind's way of seeing. It is this second meaning, rather than legal accountability, that the new tools put in doubt, and it is unlikely to be settled by rules about disclosure alone."],"difficulty":"medium"},"fs-v2-p2":{"title":"Shade as infrastructure","paras":["On a summer afternoon the centre of a large city can be several degrees hotter than the countryside around it. Asphalt and concrete absorb sunlight during the day and release it at night; air conditioners pump heat from buildings into the street; and there is little vegetation to cool the air by evaporation. Scientists call the result an urban heat island, and as heatwaves become longer and more frequent it is becoming a public-health problem rather than a curiosity.","The heat is not shared equally. Within the same city, neighbourhoods with tree-lined streets and parks can be markedly cooler than those dominated by car parks and flat roofs, and the hotter districts are often the poorer ones. Residents there are less likely to have air conditioning and more likely to work outdoors. When a heatwave strikes, the excess deaths cluster in such places.","Trees are among the most effective remedies. A mature tree shades the pavement and the walls beneath it, and the water it releases through its leaves cools the surrounding air. Yet cities often treat trees as decoration — something to be planted when budgets allow and removed when a road needs widening. Young trees are planted without the care needed to keep them alive through their first dry summers, and many die within a few years.","A growing number of planners argue that shade should be treated as infrastructure, like drains or streetlights: planned, maintained and distributed according to need. The argument is partly economic. A tree costs little to plant but takes decades to reach full size, so the benefits arrive slowly and are easily ignored in annual budgets. Cities that wait for a heatwave before planting will find that the trees they need should have been planted twenty years earlier."],"difficulty":"easy"},"fs-v2-p3":{"title":"The obligation in the gift","paras":["Anthropologists have long been fascinated by societies in which gifts, rather than markets, organise much of economic life. In the classic accounts, a gift is never simply given. It creates an obligation to receive it, and then an obligation to return it, usually with something of greater value and usually after a delay. A gift returned at once, or with something of exactly equal worth, would be an insult: it would turn a relationship into a transaction and announce that the parties wished to owe each other nothing.","From this observation it was tempting to draw a contrast between two kinds of society. In one, exchange binds people together through endless cycles of debt; in the other, the market lets strangers trade and walk away. The first was romanticised as warm and communal, the second deplored as cold and individualist, and the gift became a symbol of everything modern life had lost.","The contrast is too neat. Gift economies could be fiercely competitive: in some, rivals ruined themselves to give away more than their opponents, and the obligation to return a gift could be a heavy burden on those unable to meet it. Debt, after all, is a form of hierarchy, and the person who cannot repay is placed below the person who gave. Conversely, markets have never been as impersonal as the theory suggests. Traders cultivate regular customers, extend credit to those they know and give small gifts to keep a relationship alive.","What the anthropology of the gift shows, then, is not that one kind of society is better than another, but that every economy mixes two logics — the logic of settling accounts and the logic of keeping them open. The question worth asking of any society is how it decides which relationships should be closed by payment and which should be left, deliberately, in debt."],"difficulty":"hard"},"fs-v2-p4":{"title":"Why accents survive","paras":["Every few decades someone predicts that radio, television or the internet will erase regional accents. The prediction keeps failing. Children who grow up watching the same programmes as children hundreds of kilometres away still sound like the people in their own streets. Linguists have a simple explanation: we learn to speak mainly from people we interact with, not from voices we merely hear. A television presenter never replies, and a child does not adjust her speech to win the presenter's approval.","Accents persist also because they do social work. An accent tells listeners where a speaker comes from, and often which class or community she belongs to. That information can count against her — speakers of stigmatised accents are routinely judged less intelligent or less competent — but it can also signal loyalty and belonging. Teenagers, in particular, often exaggerate the local features of their speech, as if to mark themselves off from both their parents and the standard of the classroom.","This does not mean that accents are fixed. They change constantly, and some changes spread remarkably quickly across cities and even countries. But the changes move through networks of people who talk to one another, especially young people, rather than descending from broadcasters. A new vowel sound may appear in a city's poorer districts and spread outwards among the young while the national media go on speaking as before.","The persistence of accents is thus a small lesson in how culture travels. Mass media can spread words, phrases and fashions with great speed, but the deeper patterns of how we speak are shaped by the people whose approval we seek. Exposure is not the same as influence."],"difficulty":"medium"},"fs-v3-p1":{"title":"The ethics of return","paras":["For most of the twentieth century, a museum's account of how it acquired an object ended with the date of purchase. Where the object had been before — dug from a grave, taken in a punitive expedition, sold by a dealer who asked no questions — was treated as a matter for historians, not curators. That has changed. Museums in several countries have returned bronzes, sculptures and manuscripts to the places from which they were taken, and the question of provenance has moved from the footnote to the front page.","The case for return is strongest where the circumstances of removal are clear. An object seized by soldiers from a royal palace was not acquired in any sense a court would recognise, and the passage of time does not launder it. Many museums now accept this, at least for the most notorious cases. The harder cases are the ordinary ones: objects bought from local sellers under colonial rule, gifts from rulers who may have had little choice, finds made by excavations that the law of the time permitted.","Here two arguments collide. One holds that the law and customs of the time should govern; to judge past transactions by present standards is to make every collection permanently insecure. The other holds that colonial law was itself an instrument of the power that took the objects, and that legality under such a regime proves little about consent. Neither argument can be dismissed. The first protects against endless claims; the second refuses to let the powerful write the rules by which their acquisitions are judged.","What is emerging, slowly, is less a principle than a practice: case-by-case negotiation, shared research into provenance, long-term loans and joint exhibitions. Critics on both sides find this unsatisfying, the one because it concedes too much, the other because it concedes too little. Yet a practice that obliges museums to know and to state how their objects came to them may achieve more than any single rule. An institution that must tell the history of its possessions can no longer pretend that history began at the moment of purchase."],"difficulty":"medium"},"fs-v3-p2":{"title":"Minds in the arms","paras":["An octopus has about five hundred million neurons, roughly as many as a dog, but two-thirds of them are not in its head. They are in its arms. Each arm can taste what it touches, reach for food and even continue to respond to stimuli after being severed from the body. To an observer, an octopus exploring a rock looks less like one animal directing eight limbs than like a committee whose members consult one another only occasionally.","This arrangement makes octopuses a puzzle for students of intelligence. Octopuses solve problems that would challenge many mammals: they open jars, escape from tanks and learn by watching other octopuses. Yet their last common ancestor with vertebrates was a simple worm-like creature that lived more than five hundred million years ago. Whatever intelligence octopuses have, they evolved it independently of us, on a body plan with no skeleton and a nervous system built along quite different lines.","That independence is what makes them valuable to science. If intelligence had evolved only once, among vertebrates, it would be hard to tell which of its features were necessary and which were accidents of our particular history. The octopus offers a second experiment. Where it resembles us — in curiosity, in play, in the ability to tell individual humans apart — we may be seeing something general about what complex minds require. Where it differs, we are reminded how much of our picture of thinking is drawn from a single example.","The octopus's life, however, is short. Most species live only a year or two, and the mother usually dies soon after her eggs hatch, so there is no long childhood in which the young learn from their parents. A creature so intelligent and so brief is itself a puzzle: it suggests that intelligence can arise without the long lives and social learning that, in our own case, seemed to explain it."],"difficulty":"easy"},"fs-v3-p3":{"title":"Trusting the experts","paras":["Most of what any of us believes about the world we have not checked for ourselves. I believe that the earth orbits the sun, that smoking causes cancer and that there is a city called Ulaanbaatar, but I could not demonstrate any of these from my own observations. I believe them because I trust others: teachers, textbooks, scientists and the institutions that train and certify them. Knowledge, for creatures like us, is irreducibly social.","This dependence troubles a tradition in philosophy that takes the independent thinker as its ideal. On that view, to believe something merely because others say so is to fall short of knowing it; the rational person accepts nothing on authority and examines everything for herself. The ideal is admirable as a corrective to credulity, but taken literally it is impossible. No one has the time or the training to verify more than a sliver of what they need to know, and a person who refused all testimony would know almost nothing.","The real question, then, is not whether to trust but whom, and on what grounds. Here the layperson faces a difficulty. To judge an expert's claims directly would require the very expertise the layperson lacks. What she can judge are indirect signs: whether the expert's field has a record of reliable prediction, whether experts in it largely agree, whether they stand to gain from what they say, and whether their claims stay within the bounds of their competence. These signs are fallible, but they are not nothing.","Seen this way, the spread of distrust in experts is less a triumph of independent thinking than a shift of trust from one set of authorities to another. The person who rejects the scientific consensus on vaccines rarely does so after studying immunology; more often she has come to trust a different source — a commentator, a forum, a friend. The problem is not that she trusts, but that the signs on which her new trust rests are weaker than those she abandoned."],"difficulty":"hard"},"fs-v3-p4":{"title":"The flexible worker's bargain","paras":["The workers who deliver food, drive taxis or clean homes through digital platforms are often described as entrepreneurs. They choose their hours, accept or decline jobs and can work for several platforms at once. Platforms present this freedom as the essence of the arrangement, and many workers value it: surveys regularly find that flexibility is the feature they would least like to give up.","Yet the freedom is shaped by an algorithm the worker cannot see. A courier who declines too many orders may find fewer offered; a driver who logs off during busy hours may lose the bonus that made the evening worthwhile. Pay per job can change without notice, and the rating systems that decide who gets work are run by the platform alone. The worker is free to choose, but the menu of choices is written by someone else.","Courts and legislators have struggled to fit this arrangement into existing categories. Employment law was built around a simple distinction: employees, who work under direction and receive protection, and independent contractors, who run their own businesses and bear their own risks. Platform workers fall awkwardly between the two. They lack the protections of employees, yet they have little of the independence that makes self-employment a business rather than a job.","Some countries have responded by creating an intermediate category, granting rights such as a minimum wage for time actually worked, or access to accident insurance, without requiring fixed hours. The approach has critics. Platforms argue that it raises costs and will reduce the number of jobs; some unions argue that it entrenches a second-class status. But the alternative — forcing a new kind of work into one of two old boxes — has proved unworkable. What the gig economy has exposed is not only a gap in protection but the age of the categories through which protection is offered."],"difficulty":"medium"},"fs-v4-p1":{"title":"The narrator who cannot be trusted","paras":["Readers of fiction usually begin by believing the narrator. The voice that tells the story is our only access to its world, and we extend to it the provisional trust we extend to anyone who speaks to us. The unreliable narrator exploits this trust. Gradually, through contradictions, omissions or the reactions of other characters, we come to suspect that the teller is mistaken, self-deceived or lying, and the story we are reading splits in two: the one the narrator tells and the one we infer behind it.","Critics once treated this as a matter of the narrator's character. An unreliable narrator was a liar, a fool or a madman, and the reader's task was to diagnose the defect. More recent critics have pointed out that unreliability depends as much on the reader as on the narrator. Whether we judge a narrator's values to be distorted depends on our own values; what one generation reads as an ironic portrait of prejudice, another may read as an endorsement. Unreliability, on this view, is not a property of the text alone but a relation between a text and its readers.","This shift has an uncomfortable consequence. If unreliability is relative to readers, then the author's intention — the ‘implied author’ whose values the narrator is meant to fall short of — becomes harder to locate. We may believe we have caught the narrator out, when in fact we have merely imported assumptions the author did not share. The device that seemed to flatter the reader's perceptiveness turns out to test it.","None of this means that every reading is as good as every other. Some inferences are better supported than others, and a reader who ignores the plain evidence of a text is not reading it differently but reading it badly. But the unreliable narrator reminds us that interpretation is an activity with risks. The pleasure of seeing through a narrator comes with the possibility that we are the ones who have been seen through."],"difficulty":"hard"},"fs-v4-p2":{"title":"Railway time","paras":["Until the middle of the nineteenth century, every town kept its own time. Noon was the moment the sun stood highest overhead, and because the sun moves westward, noon in a western town came several minutes after noon in an eastern one. For people who travelled on foot or by coach, the difference hardly mattered: a journey of a day or two blurred a few minutes of local variation.","The railways changed this. A train running east to west passed through dozens of local times, and timetables that listed each station's own clock were confusing and dangerous; on single-track lines, a misreading could put two trains on the same stretch at once. Railway companies began to run their trains on a single standard time, usually that of a major city, and towns along the line gradually adjusted their public clocks to match. For a while many towns displayed two times, local and railway, and people argued over which was the ‘real’ one.","Standard time zones, adopted across much of the world by the early twentieth century, settled the argument in favour of coordination. Time became less a fact about the sun and more an agreement among people. The change was resisted at first — some saw it as an imposition by distant companies and governments — but its convenience soon made it invisible. Few people today think of the clock on their phone as a convention.","The episode is a reminder that technologies do not only solve problems; they also change what counts as a problem. The few minutes between neighbouring towns had always existed. They became a problem only when trains moved fast enough, and ran often enough, for those minutes to matter."],"difficulty":"easy"},"fs-v4-p3":{"title":"Rivers and the dams that hold them","paras":["India has built more than five thousand large dams since independence, and for decades they were celebrated as the temples of a modern nation. They irrigate fields that once depended on uncertain rains, supply cities with drinking water and generate electricity. In a country where the monsoon brings most of the year's rain in a few months, storing water for the dry season is not a luxury but a necessity.","The costs, however, were long counted only in money. Reservoirs submerged villages and forests, and the people displaced — very often from tribal and rural communities — were promised land and compensation that frequently arrived late, partially or not at all. Downstream, rivers that had flooded seasonally and spread fertile silt across their plains were turned into regulated channels; fisheries declined, and deltas, deprived of sediment, began to shrink.","Defenders of dams reply that these costs, though real, must be weighed against the benefits to many millions more. Without storage, they argue, irrigation would be impossible across large parts of the country, and the poor would suffer most from drought. Critics answer that the weighing has rarely been honest: benefits were projected generously in feasibility reports and costs, especially those borne by people with little political voice, were left out or discounted.","Recent policy has moved, unevenly, towards a fuller accounting. Environmental clearance now requires assessments of downstream effects, and resettlement law demands consent and compensation at higher rates. Some engineers now speak of ‘environmental flows’ — releasing enough water to keep a river alive as a river. The question is no longer only whether to build, but how to manage a river as a living system rather than as a pipe."],"difficulty":"medium"},"fs-v4-p4":{"title":"Remembering to change","paras":["For most of the twentieth century, neuroscientists believed that memories, once formed, were fixed. A new memory was fragile for a few hours, while the brain consolidated it, but after that it was stored more or less permanently, like a document placed in a filing cabinet. Recalling it meant taking the document out and reading it; the document itself did not change.","Experiments beginning around the year 2000 challenged this picture. Researchers trained rats to fear a tone by pairing it with a mild shock, waited until the memory was consolidated, and then played the tone again while giving the rats a drug that blocks the formation of new memories. The rats later showed much less fear of the tone. Recalling the memory, it seemed, had made it fragile again, so that it had to be stored afresh — a process called reconsolidation — and the drug had disrupted the restoring.","The finding suggested that memory is less a record than a process. Each time a memory is recalled, it can be updated with new information, strengthened, weakened or altered. This may serve a purpose: a memory that could never change would become less accurate as the world changed around it. But it also helps explain why memories drift, and why people can come to remember, sincerely, events that did not happen as they recall them.","The clinical hopes raised by reconsolidation have been partly realised. Some studies have found that recalling a traumatic memory under certain conditions can reduce its emotional force, though results have been mixed and the conditions under which a memory becomes changeable are still not fully understood. The broader lesson may be the more durable one: that remembering is not the opposite of forgetting, but a way of rewriting."],"difficulty":"medium"}},"questions":[{"id":"fs-q1-1","topic":"qa-arith","difficulty":"easy","src":"final","stem":"A vessel holds 80 litres of pure milk. 16 litres are taken out and replaced with water. Then 20 litres of the mixture are taken out and replaced with water. How many litres of milk are now in the vessel?","explanation":"Each round keeps a fraction of the milk: 80 × (64/80) × (60/80) = 48.\nSignal: replacement template, 30-second sitter. Attempt first.","type":"tita","answer":"48","numeric":true},{"id":"fs-q1-2","topic":"qa-alg","difficulty":"easy","src":"final","stem":"If log₂x + log₄x + log₁₆x = 7, what is the value of x?","explanation":"Convert to base 2: log₂x × (1 + 1/2 + 1/4) = 7 → (7/4)·log₂x = 7 → log₂x = 4 → x = 16.\nSignal: change of base, one line.","type":"tita","answer":"16","numeric":true},{"id":"fs-q1-3","topic":"qa-arith","difficulty":"medium","src":"final","stem":"Two cars start at the same time from towns A and B, driving towards each other. After they meet, the car from A takes 1 hour 40 minutes to reach B and the car from B takes 2 hours 24 minutes to reach A. If the faster car runs at 60 km/h, what is the distance AB?","explanation":"Speed ratio = √(time of other ÷ own time) = √((12/5) ÷ (5/3)) = 6/5, so the cars run at 60 and 50 km/h. They meet after √((5/3)(12/5)) = 2 hours. Distance = (60 + 50) × 2 = 220 km.\nSignal: 'after meeting, takes a and b hours' → speeds ∝ √b : √a.","type":"mcq","options":[{"k":"A","t":"240 km"},{"k":"B","t":"200 km"},{"k":"C","t":"220 km"},{"k":"D","t":"264 km"}],"answer":"C"},{"id":"fs-q1-4","topic":"qa-alg","difficulty":"medium","src":"final","stem":"The equations x² − 7x + 12 = 0 and x² − kx + 15 = 0 have exactly one root in common. What is the sum of all possible values of k?","explanation":"Roots of the first are 3 and 4. Root 3: 9 − 3k + 15 = 0 → k = 8 (other root 5). Root 4: 16 − 4k + 15 = 0 → k = 31/4 (other root 15/4). Both give exactly one common root, so the sum is 8 + 7.75 = 15.75.\nSignal: common-root template (2024 S1, 2025 S2). Plug each root of the easy quadratic.","type":"mcq","options":[{"k":"A","t":"7.75"},{"k":"B","t":"8"},{"k":"C","t":"15.75"},{"k":"D","t":"16.25"}],"answer":"C"},{"id":"fs-q1-5","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A alone can finish a job in 10 days, B in 15 days and C in 20 days. A and B work on day 1, B and C on day 2, C and A on day 3, and this pattern repeats until the job is done. On how many days does C work?","explanation":"Take the job as 60 units: A 6, B 4, C 3 a day. Day totals: 10, 7, 9 → 26 per 3-day cycle. After 6 days 52 are done; day 7 (A + B) adds 10 and finishes. C worked on days 2, 3, 5, 6 = 4 days.\nSignal: rotating roster (2022 S3, 2024 S3). Use LCM units and walk the last cycle.","type":"tita","answer":"4","numeric":true},{"id":"fs-q1-6","topic":"qa-num","difficulty":"medium","src":"final","stem":"What is the remainder when 7¹⁰⁰ is divided by 13?","explanation":"7¹² ≡ 1 (mod 13) (Fermat). 100 = 12 × 8 + 4, so 7¹⁰⁰ ≡ 7⁴. 7² = 49 ≡ 10, 7⁴ ≡ 100 ≡ 9.\nSignal: remainder of a large power — appeared in every 2024 slot.","type":"tita","answer":"9","numeric":true},{"id":"fs-q1-7","topic":"qa-arith","difficulty":"easy","src":"final","stem":"A shopkeeper marks his goods 50% above cost price and offers 'buy 4, get 1 free'. What is his profit percentage on a customer who takes 5 items?","explanation":"For 5 items the cost is 5c and he collects 4 × 1.5c = 6c. Profit = c on 5c = 20%.\nSignal: free item = cost with no revenue (2025 S1 pattern).","type":"mcq","options":[{"k":"A","t":"15%"},{"k":"B","t":"12.5%"},{"k":"C","t":"25%"},{"k":"D","t":"20%"}],"answer":"D"},{"id":"fs-q1-8","topic":"qa-alg","difficulty":"easy","src":"final","stem":"The sum of the first n terms of an arithmetic progression is 3n² + 5n. What is its 15th term?","explanation":"T₁₅ = S₁₅ − S₁₄ = 3(225 − 196) + 5 = 92.\nSignal: Tₙ = Sₙ − Sₙ₋₁. Ten seconds.","type":"tita","answer":"92","numeric":true},{"id":"fs-q1-9","topic":"qa-arith","difficulty":"medium","src":"final","stem":"₹20,000 is invested for 2 years at 10% per annum compound interest. The whole amount is then invested for 3 years at 12% per annum simple interest. What is the final amount?","explanation":"After 2 years: 20,000 × 1.21 = 24,200. Simple interest for 3 years at 12% adds 36%: 24,200 × 1.36 = 32,912.\nSignal: compound-then-simple reinvestment (2023 S1, repeated in 2024).","type":"mcq","options":[{"k":"A","t":"₹31,944"},{"k":"B","t":"₹33,124"},{"k":"C","t":"₹32,400"},{"k":"D","t":"₹32,912"}],"answer":"D"},{"id":"fs-q1-10","topic":"qa-alg","difficulty":"medium","src":"final","stem":"How many integers x satisfy |x − 3| + |x + 5| < 14?","explanation":"Between −5 and 3 the sum is always 8 (9 integers). For x > 3: 2x + 2 < 14 → x = 4, 5. For x < −5: −2x − 2 < 14 → x = −6, −7. Total 9 + 2 + 2 = 13.\nSignal: sum of distances on a number line — flat between the points.","type":"mcq","options":[{"k":"A","t":"11"},{"k":"B","t":"12"},{"k":"C","t":"13"},{"k":"D","t":"14"}],"answer":"C"},{"id":"fs-q1-11","topic":"qa-geo","difficulty":"easy","src":"final","stem":"A right-angled triangle has sides 20 cm, 21 cm and 29 cm. What is the area of its inscribed circle?","explanation":"For a right triangle r = (a + b − c)/2 = (20 + 21 − 29)/2 = 6, so the area is 36π.\nSignal: incircle of a right triangle, one formula.","type":"mcq","options":[{"k":"A","t":"36π cm²"},{"k":"B","t":"25π cm²"},{"k":"C","t":"49π cm²"},{"k":"D","t":"30π cm²"}],"answer":"A"},{"id":"fs-q1-12","topic":"qa-alg","difficulty":"hard","src":"final","stem":"What is the value of [√1] + [√2] + [√3] + … + [√50], where [x] is the greatest integer less than or equal to x?","explanation":"[√k] = v for the 2v + 1 numbers from v² to (v + 1)² − 1. Sum = 1·3 + 2·5 + 3·7 + 4·9 + 5·11 + 6·13 + 7·2 (only 49 and 50) = 3 + 10 + 21 + 36 + 55 + 78 + 14 = 217.\nSignal: [x] sums (2022 S1, 2024 S1, 2025 S1). Group equal values; watch the last partial block.","type":"tita","answer":"217","numeric":true},{"id":"fs-q1-13","topic":"qa-arith","difficulty":"medium","src":"final","stem":"In what ratio should mixture X (milk : water = 5 : 3) be mixed with mixture Y (milk : water = 7 : 5) so that the result has milk : water = 3 : 2? If 20 litres of the result are needed, how many litres of X are used?","explanation":"Milk fractions: X = 0.625, Y = 0.5833, target 0.6. Alligation: X : Y = (0.6 − 0.5833) : (0.625 − 0.6) = 1/60 : 1/40 = 2 : 3. X = 2/5 of 20 = 8 litres.\nSignal: alligation on the milk fraction.","type":"mcq","options":[{"k":"A","t":"6"},{"k":"B","t":"8"},{"k":"C","t":"10"},{"k":"D","t":"12"}],"answer":"B"},{"id":"fs-q1-14","topic":"qa-alg","difficulty":"easy","src":"final","stem":"What is the sum of the roots of 4ˣ − 6·2ˣ + 8 = 0?","explanation":"Put y = 2ˣ: y² − 6y + 8 = 0 → y = 2 or 4 → x = 1 or 2. Sum 3.\nSignal: substitution turns it into a quadratic.","type":"mcq","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"6"}],"answer":"C"},{"id":"fs-q1-15","topic":"qa-arith","difficulty":"medium","src":"final","stem":"The average of 15 distinct positive integers is 30 and the smallest of them is 12. What is the largest possible value of the greatest of them?","explanation":"Total = 450. The other 14 numbers are at least 12, 13, …, 25, which sum to 259. Largest = 450 − 259 = 191.\nSignal: max/min with a fixed total (2021 S3, 2024 S3).","type":"mcq","options":[{"k":"A","t":"189"},{"k":"B","t":"191"},{"k":"C","t":"193"},{"k":"D","t":"205"}],"answer":"B"},{"id":"fs-q1-16","topic":"qa-geo","difficulty":"medium","src":"final","stem":"A regular hexagon ABCDEF has an area of 72 cm². What is the area of the quadrilateral ABDE, in cm²?","explanation":"ABDE is a rectangle with sides s and s√3, area √3·s². The hexagon is (3√3/2)·s². Ratio = 2/3, so ABDE = 48.\nSignal: regular hexagon = 6 equilateral triangles (repeats 2021–2025).","type":"tita","answer":"48","numeric":true},{"id":"fs-q1-17","topic":"qa-alg","difficulty":"medium","src":"final","stem":"A function f satisfies f(x) + 2f(1/x) = 3x for every x ≠ 0. What is f(2)?","explanation":"Put x = 2: f(2) + 2f(½) = 6. Put x = ½: f(½) + 2f(2) = 3/2. Solving, f(½) = 3/2 − 2f(2), so f(2) + 3 − 4f(2) = 6 → f(2) = −1.\nSignal: functional equation with x and 1/x — write both, solve two equations.","type":"mcq","options":[{"k":"A","t":"−2"},{"k":"B","t":"−1"},{"k":"C","t":"1"},{"k":"D","t":"2"}],"answer":"B"},{"id":"fs-q1-18","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A and B run on a circular track of 900 m from the same point. Running in the same direction, A first overtakes B after 12 minutes. Running in opposite directions, they meet for the third time after 6 minutes. What is B's speed in m/min?","explanation":"Difference = 900/12 = 75 m/min. Third meeting after 6 min: sum × 6 = 3 × 900 → sum = 450. B = (450 − 75)/2 = 187.5.\nSignal: circular track — same direction uses the difference, opposite uses the sum.","type":"mcq","options":[{"k":"A","t":"175"},{"k":"B","t":"187.5"},{"k":"C","t":"225"},{"k":"D","t":"262.5"}],"answer":"B"},{"id":"fs-q1-19","topic":"qa-alg","difficulty":"medium","src":"final","stem":"If α and β are the roots of x² − 6x + 4 = 0, what is the value of √α + √β?","explanation":"(√α + √β)² = α + β + 2√(αβ) = 6 + 2·2 = 10, so √α + √β = √10 (both roots are positive).\nSignal: square the expression you want.","type":"mcq","options":[{"k":"A","t":"√12"},{"k":"B","t":"√14"},{"k":"C","t":"√10"},{"k":"D","t":"2√2"}],"answer":"C"},{"id":"fs-q1-20","topic":"qa-num","difficulty":"medium","src":"final","stem":"How many factors of 2⁴ × 3³ × 5² are perfect squares?","explanation":"A square factor uses even powers: 2⁰,², ⁴ (3 ways), 3⁰,² (2 ways), 5⁰,² (2 ways) → 12.","type":"mcq","options":[{"k":"A","t":"9"},{"k":"B","t":"12"},{"k":"C","t":"16"},{"k":"D","t":"18"}],"answer":"B"},{"id":"fs-q1-21","topic":"qa-geo","difficulty":"hard","src":"final","stem":"Two circles of radii 10 cm and 17 cm intersect, and their common chord is 16 cm long. If the centres lie on opposite sides of the chord, how far apart are the centres?","explanation":"Each centre's distance to the chord: √(10² − 8²) = 6 and √(17² − 8²) = 15. On opposite sides they add: 21 cm.\nSignal: perpendicular from the centre bisects a chord.","type":"mcq","options":[{"k":"A","t":"19 cm"},{"k":"B","t":"23 cm"},{"k":"C","t":"21 cm"},{"k":"D","t":"9 cm"}],"answer":"C"},{"id":"fs-q1-22","topic":"qa-mod","difficulty":"hard","src":"final","stem":"How many integers from 1 to 600 (both inclusive) have all their digits different?","explanation":"1-digit: 9. 2-digit: 9 × 9 = 81. 3-digit from 100 to 599: 5 × 9 × 8 = 360 (600 repeats a 0). Total 450.\nSignal: non-repeating digits (2020, 2023 S1, 2024 S3). Split by number of digits; check the upper end.","type":"tita","answer":"450","numeric":true},{"id":"fs-q2-1","topic":"qa-arith","difficulty":"easy","src":"final","stem":"The price of sugar rises by 25%. By what percentage must a family reduce its consumption so that its spending on sugar does not change?","explanation":"New consumption = 1/1.25 = 0.8 of the old, a 20% cut.\nSignal: r/(100 + r) shortcut.","type":"mcq","options":[{"k":"A","t":"20%"},{"k":"B","t":"22%"},{"k":"C","t":"25%"},{"k":"D","t":"16.67%"}],"answer":"A"},{"id":"fs-q2-2","topic":"qa-alg","difficulty":"easy","src":"final","stem":"In a geometric progression the 3rd term is 24 and the 6th term is 192. What is the sum of the first 5 terms?","explanation":"r³ = 192/24 = 8 → r = 2, a = 6. S₅ = 6(2⁵ − 1) = 186.","type":"mcq","options":[{"k":"A","t":"180"},{"k":"B","t":"186"},{"k":"C","t":"192"},{"k":"D","t":"372"}],"answer":"B"},{"id":"fs-q2-3","topic":"qa-arith","difficulty":"medium","src":"final","stem":"Running up a moving escalator at 2 steps per second, Ravi reaches the top in 20 seconds. At 3 steps per second he takes 16 seconds. How many steps are visible on the escalator?","explanation":"Steps = time × (own rate + escalator rate): 20(2 + e) = 16(3 + e) → e = 2 → 20 × 4 = 80.\nSignal: escalator/boat template (2022 S3, 2025 S2).","type":"tita","answer":"80","numeric":true},{"id":"fs-q2-4","topic":"qa-alg","difficulty":"medium","src":"final","stem":"How many integers x satisfy log₂(x − 1) + log₂(x + 1) ≤ 3?","explanation":"Domain: x > 1. Then (x − 1)(x + 1) ≤ 8 → x² ≤ 9 → x ≤ 3. Integers 2 and 3.\nSignal: never forget the domain of a log.","type":"tita","answer":"2","numeric":true},{"id":"fs-q2-5","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A and B together can finish a job in 10 days, B and C in 15 days, and C and A in 12 days. How many days would A alone take?","explanation":"All three together: (1/10 + 1/15 + 1/12)/2 = 1/8 per day. A = 1/8 − 1/15 = 7/120 → 120/7 days.\nSignal: three workers given in pairs — add and halve.","type":"mcq","options":[{"k":"A","t":"40/3"},{"k":"B","t":"24"},{"k":"C","t":"120/7"},{"k":"D","t":"20"}],"answer":"C"},{"id":"fs-q2-6","topic":"qa-alg","difficulty":"medium","src":"final","stem":"For which values of k does x² − (k + 1)x + (k + 4) = 0 have two real roots that are both positive?","explanation":"Real roots: (k + 1)² − 4(k + 4) ≥ 0 → (k − 5)(k + 3) ≥ 0 → k ≤ −3 or k ≥ 5. Positive roots: sum k + 1 > 0 and product k + 4 > 0 → k > −1. Together: k ≥ 5.","type":"mcq","options":[{"k":"A","t":"−1 < k < 5"},{"k":"B","t":"k > −4"},{"k":"C","t":"k ≤ −3"},{"k":"D","t":"k ≥ 5"}],"answer":"D"},{"id":"fs-q2-7","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A trader buys goods at 10% below the list price and sells them at 20% above the list price, but gives one item free with every nine sold. What is his profit percentage?","explanation":"For 10 items: cost 10 × 0.9L = 9L, revenue 9 × 1.2L = 10.8L. Profit = 1.8L on 9L = 20%.","type":"tita","answer":"20","numeric":true},{"id":"fs-q2-8","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A invests ₹30,000 at the start of a year. B joins after 4 months with ₹40,000 and C after 6 months with ₹50,000. Out of a year-end profit of ₹98,000, what is C's share?","explanation":"Capital × months: A 3,60,000, B 3,20,000, C 3,00,000 → 18 : 16 : 15. C = 15/49 × 98,000 = 30,000.","type":"mcq","options":[{"k":"A","t":"₹32,000"},{"k":"B","t":"₹28,000"},{"k":"C","t":"₹36,000"},{"k":"D","t":"₹30,000"}],"answer":"D"},{"id":"fs-q2-9","topic":"qa-alg","difficulty":"easy","src":"final","stem":"3 pens and 5 pencils cost ₹81; 5 pens and 3 pencils cost ₹103. What is the cost of one pen and one pencil together, in ₹?","explanation":"Add the two: 8 pens + 8 pencils = 184, so one of each costs 23.\nSignal: add the equations — no need to solve for each.","type":"tita","answer":"23","numeric":true},{"id":"fs-q2-10","topic":"qa-arith","difficulty":"easy","src":"final","stem":"The difference between compound interest and simple interest on a sum for 3 years at 10% per annum is ₹930. What is the sum?","explanation":"CI − SI for 3 years = P(1.331 − 1 − 0.3) = 0.031P = 930 → P = 30,000.","type":"mcq","options":[{"k":"A","t":"₹33,000"},{"k":"B","t":"₹27,000"},{"k":"C","t":"₹31,000"},{"k":"D","t":"₹30,000"}],"answer":"D"},{"id":"fs-q2-11","topic":"qa-alg","difficulty":"medium","src":"final","stem":"Let f(x) = (x + 1)/(x − 1). What is the value of f applied 2027 times to 3, that is f(f(…f(3)…))?","explanation":"f(f(x)) = x for this f, so applying it an odd number of times equals applying it once: f(3) = 4/2 = 2.\nSignal: compute f(f(x)) first — it is often x.","type":"mcq","options":[{"k":"A","t":"1/2"},{"k":"B","t":"3"},{"k":"C","t":"2"},{"k":"D","t":"−2"}],"answer":"C"},{"id":"fs-q2-12","topic":"qa-geo","difficulty":"easy","src":"final","stem":"A triangle has sides 13 cm, 14 cm and 15 cm. What is the length of the altitude to the 14 cm side, in cm?","explanation":"Heron: s = 21, area = √(21 × 8 × 7 × 6) = 84. Altitude = 2 × 84/14 = 12.\nSignal: 13-14-15 has area 84 — worth remembering.","type":"tita","answer":"12","numeric":true},{"id":"fs-q2-13","topic":"qa-alg","difficulty":"medium","src":"final","stem":"How many pairs of positive integers (x, y) satisfy 3x + 5y = 101?","explanation":"y must leave 101 − 5y divisible by 3, so y ≡ 1 (mod 3): y = 1, 4, 7, 10, 13, 16, 19 (x stays positive). 7 pairs.","type":"tita","answer":"7","numeric":true},{"id":"fs-q2-14","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A jar holds 60 litres of a 40% acid solution. x litres are taken out and replaced with water, and this is done once more. The acid concentration is now 22.5%. What is x?","explanation":"(1 − x/60)² = 22.5/40 = 0.5625 → 1 − x/60 = 0.75 → x = 15.","type":"mcq","options":[{"k":"A","t":"10"},{"k":"B","t":"12"},{"k":"C","t":"15"},{"k":"D","t":"20"}],"answer":"C"},{"id":"fs-q2-15","topic":"qa-geo","difficulty":"medium","src":"final","stem":"An isosceles trapezium with parallel sides 8 cm and 18 cm has a circle inscribed in it. What is the radius of the circle?","explanation":"A trapezium with an incircle has legs summing to the parallel sides: each leg = 13. Height = √(13² − 5²) = 12, so r = 6.\nSignal: circle inscribed in a trapezium (2021 S1, 2024 S1, 2025 S3).","type":"mcq","options":[{"k":"A","t":"5 cm"},{"k":"B","t":"6 cm"},{"k":"C","t":"6.5 cm"},{"k":"D","t":"12 cm"}],"answer":"B"},{"id":"fs-q2-16","topic":"qa-alg","difficulty":"easy","src":"final","stem":"How many terms of the AP 3, 7, 11, … must be added to get a sum of 820?","explanation":"Sₙ = n/2 × (6 + 4(n − 1)) = n(2n + 1) = 820 → n = 20.","type":"mcq","options":[{"k":"A","t":"19"},{"k":"B","t":"20"},{"k":"C","t":"21"},{"k":"D","t":"22"}],"answer":"B"},{"id":"fs-q2-17","topic":"qa-num","difficulty":"medium","src":"final","stem":"Two numbers have HCF 12 and LCM 360. How many such pairs of numbers are there?","explanation":"Write them as 12a and 12b with a, b coprime and ab = 30 = 2 × 3 × 5. Unordered coprime splits: (1,30), (2,15), (3,10), (5,6) → 4.","type":"mcq","options":[{"k":"A","t":"3"},{"k":"B","t":"4"},{"k":"C","t":"6"},{"k":"D","t":"8"}],"answer":"B"},{"id":"fs-q2-18","topic":"qa-alg","difficulty":"hard","src":"final","stem":"x and y are positive real numbers with x + y = 10. What is the maximum value of x²y?","explanation":"AM–GM on x/2, x/2, y (sum 10): x²y/4 ≤ (10/3)³, maximum when x/2 = y → x = 20/3, y = 10/3. x²y = 4000/27.","type":"mcq","options":[{"k":"A","t":"160"},{"k":"B","t":"125"},{"k":"C","t":"4000/27"},{"k":"D","t":"1000/9"}],"answer":"C"},{"id":"fs-q2-19","topic":"qa-num","difficulty":"hard","src":"final","stem":"What are the last two digits of 7²⁰²⁶?","explanation":"7⁴ = 2401 ends in 01, so powers of 7 repeat every 4 in the last two digits. 2026 = 4 × 506 + 2 → 7² = 49.","type":"tita","answer":"49","numeric":true},{"id":"fs-q2-20","topic":"qa-geo","difficulty":"easy","src":"final","stem":"What is the area of the triangle with vertices (1, 2), (4, 6) and (7, −1)?","explanation":"½|1(6 + 1) + 4(−1 − 2) + 7(2 − 6)| = ½|7 − 12 − 28| = 16.5.","type":"mcq","options":[{"k":"A","t":"15"},{"k":"B","t":"16.5"},{"k":"C","t":"18"},{"k":"D","t":"33"}],"answer":"B"},{"id":"fs-q2-21","topic":"qa-arith","difficulty":"easy","src":"final","stem":"A train passes a pole in 12 seconds and a 300 m long platform in 27 seconds. How long is the train, in metres?","explanation":"The extra 15 seconds cover the platform: speed = 20 m/s. Length = 20 × 12 = 240.","type":"tita","answer":"240","numeric":true},{"id":"fs-q2-22","topic":"qa-mod","difficulty":"medium","src":"final","stem":"Two fair dice are thrown. What is the probability that the sum is a prime number?","explanation":"Prime sums: 2 (1 way), 3 (2), 5 (4), 7 (6), 11 (2) = 15 of 36 = 5/12.","type":"mcq","options":[{"k":"A","t":"7/18"},{"k":"B","t":"5/12"},{"k":"C","t":"1/3"},{"k":"D","t":"1/2"}],"answer":"B"},{"id":"fs-q3-1","topic":"qa-arith","difficulty":"easy","src":"final","stem":"A's salary is 25% more than B's. By what percentage is B's salary less than A's?","explanation":"B/A = 1/1.25 = 0.8, so B is 20% less.","type":"mcq","options":[{"k":"A","t":"15%"},{"k":"B","t":"25%"},{"k":"C","t":"20%"},{"k":"D","t":"22.5%"}],"answer":"C"},{"id":"fs-q3-2","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A 50-litre drum is full of oil. 10 litres are drawn out and replaced with kerosene. This is done two more times (three times in all). How many litres of oil are left?","explanation":"Each round keeps 4/5 of the oil: 50 × (4/5)³ = 25.6.","type":"tita","answer":"25.6","numeric":true},{"id":"fs-q3-3","topic":"qa-alg","difficulty":"easy","src":"final","stem":"If 2ᵃ = 5 and 5ᵇ = 8, what is the value of ab?","explanation":"a = log₂5 and b = log₅8, so ab = log₂8 = 3.\nSignal: chain of logs collapses.","type":"tita","answer":"3","numeric":true},{"id":"fs-q3-4","topic":"qa-arith","difficulty":"easy","src":"final","stem":"A can finish a job in 8 days and B in 12 days. Working together, they are paid ₹6,000. What is A's share?","explanation":"Wages split in the ratio of work rates 1/8 : 1/12 = 3 : 2 → A gets 3,600.","type":"mcq","options":[{"k":"A","t":"₹3,600"},{"k":"B","t":"₹2,400"},{"k":"C","t":"₹3,000"},{"k":"D","t":"₹4,000"}],"answer":"A"},{"id":"fs-q3-5","topic":"qa-alg","difficulty":"medium","src":"final","stem":"The equations x² − 3x + 2 = 0 and x² + kx − 4 = 0 have a common root. What is the sum of all possible values of k?","explanation":"Roots of the first: 1 and 2. Root 1 → 1 + k − 4 = 0 → k = 3. Root 2 → 4 + 2k − 4 = 0 → k = 0. Sum 3.","type":"mcq","options":[{"k":"A","t":"−3"},{"k":"B","t":"0"},{"k":"C","t":"2"},{"k":"D","t":"3"}],"answer":"D"},{"id":"fs-q3-6","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A cyclist leaves town P at 7:00 am riding towards Q at 15 km/h. Another leaves Q at 8:00 am riding towards P at 20 km/h. P and Q are 120 km apart. How far from P (in km) do they meet?","explanation":"By 8:00 the first has ridden 15 km; the remaining 105 km close at 35 km/h → 3 hours. First rider: 4 h × 15 = 60 km.","type":"tita","answer":"60","numeric":true},{"id":"fs-q3-7","topic":"qa-alg","difficulty":"medium","src":"final","stem":"What is the smallest real number x that satisfies [x] + [2x] = 13, where [·] is the greatest integer function?","explanation":"Let x = n + f. [2x] = 2n (f < ½) or 2n + 1 (f ≥ ½). 3n = 13 has no integer solution; 3n + 1 = 13 → n = 4 with f ≥ ½. So x ∈ [4.5, 5); the smallest is 4.5.","type":"tita","answer":"4.5","numeric":true},{"id":"fs-q3-8","topic":"qa-arith","difficulty":"easy","src":"final","stem":"A retailer sells an article for ₹1,500. The manufacturer, the wholesaler and the retailer each made profits of 20%, 25% and 25% respectively. What did the article cost the manufacturer?","explanation":"1,500 ÷ (1.2 × 1.25 × 1.25) = 1,500 ÷ 1.875 = 800.","type":"mcq","options":[{"k":"A","t":"₹900"},{"k":"B","t":"₹840"},{"k":"C","t":"₹750"},{"k":"D","t":"₹800"}],"answer":"D"},{"id":"fs-q3-9","topic":"qa-arith","difficulty":"medium","src":"final","stem":"Pipes A and B fill a tank in 20 and 30 minutes; pipe C empties it in 15 minutes. A and B are opened together on an empty tank, and C is opened as well after 6 minutes. In how many minutes from the start is the tank full?","explanation":"In 6 minutes A + B fill 6 × (1/20 + 1/30) = 1/2. With all three the net rate is 1/20 + 1/30 − 1/15 = 1/60, so the other half takes 30 minutes. Total 36.","type":"tita","answer":"36","numeric":true},{"id":"fs-q3-10","topic":"qa-alg","difficulty":"easy","src":"final","stem":"What is the value of 1/(1·2) + 1/(2·3) + 1/(3·4) + … + 1/(49·50)?","explanation":"1/(k(k + 1)) = 1/k − 1/(k + 1); the sum telescopes to 1 − 1/50.","type":"mcq","options":[{"k":"A","t":"48/49"},{"k":"B","t":"1"},{"k":"C","t":"49/50"},{"k":"D","t":"50/51"}],"answer":"C"},{"id":"fs-q3-11","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A sum amounts to ₹17,640 in 2 years and ₹18,522 in 3 years at compound interest. What is the sum?","explanation":"Rate = 882/17,640 = 5%. Sum = 17,640 ÷ 1.05² = 16,000.","type":"mcq","options":[{"k":"A","t":"₹16,500"},{"k":"B","t":"₹16,000"},{"k":"C","t":"₹15,500"},{"k":"D","t":"₹15,000"}],"answer":"B"},{"id":"fs-q3-12","topic":"qa-alg","difficulty":"medium","src":"final","stem":"For how many integer values of k does x² + kx + 24 = 0 have integer roots?","explanation":"The roots multiply to 24: (1,24), (2,12), (3,8), (4,6) and their negatives. k = −(sum) gives ±25, ±14, ±11, ±10 → 8 values.","type":"mcq","options":[{"k":"A","t":"4"},{"k":"B","t":"6"},{"k":"C","t":"8"},{"k":"D","t":"10"}],"answer":"C"},{"id":"fs-q3-13","topic":"qa-alg","difficulty":"medium","src":"final","stem":"What is the minimum value of |x − 1| + |x − 4| + |x − 9| over all real x?","explanation":"The sum of distances is least at the median point x = 4: 3 + 0 + 5 = 8.\nSignal: odd number of points → put x at the middle one.","type":"tita","answer":"8","numeric":true},{"id":"fs-q3-14","topic":"qa-arith","difficulty":"easy","src":"final","stem":"The present ages of A and B are in the ratio 4 : 5. Six years ago the ratio was 2 : 3. What will be the sum of their ages 5 years from now?","explanation":"(4k − 6)/(5k − 6) = 2/3 → k = 3: ages 12 and 15. In 5 years: 17 + 20 = 37.","type":"mcq","options":[{"k":"A","t":"27"},{"k":"B","t":"32"},{"k":"C","t":"37"},{"k":"D","t":"42"}],"answer":"C"},{"id":"fs-q3-15","topic":"qa-geo","difficulty":"medium","src":"final","stem":"What is the area of a regular octagon with side 2 cm?","explanation":"Area of a regular octagon = 2(1 + √2)s² = 8(1 + √2).\nSignal: octagon = square with four corners cut (corner legs s/√2).","type":"mcq","options":[{"k":"A","t":"4(1 + √2) cm²"},{"k":"B","t":"16 cm²"},{"k":"C","t":"(8 + 4√2) cm²"},{"k":"D","t":"8(1 + √2) cm²"}],"answer":"D"},{"id":"fs-q3-16","topic":"qa-alg","difficulty":"hard","src":"final","stem":"Three positive numbers are in arithmetic progression and add up to 15. If 1, 4 and 19 are added to them respectively, the results are in geometric progression. What is the largest of the three numbers?","explanation":"Take 5 − d, 5, 5 + d. Then (6 − d), 9, (24 + d) is a GP: 81 = (6 − d)(24 + d) → d² + 18d − 63 = 0 → d = 3 (d = −21 makes a number negative). Numbers 2, 5, 8.","type":"mcq","options":[{"k":"A","t":"7"},{"k":"B","t":"8"},{"k":"C","t":"9"},{"k":"D","t":"26"}],"answer":"B"},{"id":"fs-q3-17","topic":"qa-geo","difficulty":"easy","src":"final","stem":"In triangle ABC, AB = 12, AC = 18 and BC = 20. The bisector of angle A meets BC at D. What is the length of BD?","explanation":"The bisector divides BC in the ratio AB : AC = 2 : 3, so BD = 20 × 2/5 = 8.","type":"tita","answer":"8","numeric":true},{"id":"fs-q3-18","topic":"qa-alg","difficulty":"easy","src":"final","stem":"What is the minimum value of (x² + 9)/x for x > 0?","explanation":"x + 9/x ≥ 2√9 = 6, at x = 3.","type":"mcq","options":[{"k":"A","t":"3"},{"k":"B","t":"4.5"},{"k":"C","t":"6"},{"k":"D","t":"9"}],"answer":"C"},{"id":"fs-q3-19","topic":"qa-geo","difficulty":"medium","src":"final","stem":"A sector of angle 216° is cut from a circle of radius 10 cm and rolled into a cone. What is the volume of the cone?","explanation":"Slant height 10. Base circumference = (216/360) × 20π = 12π → r = 6, height = 8. Volume = (1/3)π × 36 × 8 = 96π.","type":"mcq","options":[{"k":"A","t":"72π cm³"},{"k":"B","t":"96π cm³"},{"k":"C","t":"128π cm³"},{"k":"D","t":"120π cm³"}],"answer":"B"},{"id":"fs-q3-20","topic":"qa-num","difficulty":"easy","src":"final","stem":"How many zeros does 125! end with?","explanation":"⌊125/5⌋ + ⌊125/25⌋ + ⌊125/125⌋ = 25 + 5 + 1 = 31.","type":"mcq","options":[{"k":"A","t":"25"},{"k":"B","t":"28"},{"k":"C","t":"30"},{"k":"D","t":"31"}],"answer":"D"},{"id":"fs-q3-21","topic":"qa-num","difficulty":"medium","src":"final","stem":"What is the remainder when 3²⁰²⁶ is divided by 7?","explanation":"3⁶ ≡ 1 (mod 7). 2026 = 6 × 337 + 4, so 3²⁰²⁶ ≡ 3⁴ = 81 ≡ 4.","type":"mcq","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"4"},{"k":"D","t":"5"}],"answer":"C"},{"id":"fs-q3-22","topic":"qa-mod","difficulty":"hard","src":"final","stem":"In a group of 100 students, 80 like tea, 75 like coffee and 70 like juice. What is the minimum possible number of students who like all three?","explanation":"Students missing at least one drink: at most 20 + 25 + 30 = 75 (if each misses only one). So at least 100 − 75 = 25 like all three.\nSignal: three-set Venn min/max (2020 S2, 2022 S1, 2025 S3). Count the 'misses'.","type":"tita","answer":"25","numeric":true},{"id":"fs-q4-1","topic":"qa-arith","difficulty":"easy","src":"final","stem":"The average of 10 numbers is 24. If one of them, 42, is replaced by 22, what is the new average?","explanation":"Total falls by 20, so the average falls by 2: 22.","type":"mcq","options":[{"k":"A","t":"21"},{"k":"B","t":"22"},{"k":"C","t":"22.5"},{"k":"D","t":"23"}],"answer":"B"},{"id":"fs-q4-2","topic":"qa-alg","difficulty":"easy","src":"final","stem":"What is the value of log₂3 × log₃4 × log₄5 × … × log₆₃64?","explanation":"The chain telescopes to log₂64 = 6.","type":"mcq","options":[{"k":"A","t":"5"},{"k":"B","t":"6"},{"k":"C","t":"32"},{"k":"D","t":"64"}],"answer":"B"},{"id":"fs-q4-3","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A boat goes 30 km upstream and 44 km downstream in 10 hours. It goes 40 km upstream and 55 km downstream in 13 hours. What is the speed of the boat in still water, in km/h?","explanation":"Let u = 1/upstream speed, v = 1/downstream speed: 30u + 44v = 10, 40u + 55v = 13 → v = 1/11, u = 1/5. Upstream 5, downstream 11, so still water = 8.","type":"tita","answer":"8","numeric":true},{"id":"fs-q4-4","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A, B and C alone can finish a job in 12, 15 and 20 days. A works alone on day 1, B alone on day 2, C alone on day 3, and so on in that order. On which day is the job completed?","explanation":"Job = 60 units: A 5, B 4, C 3. Each 3-day cycle does 12. After 4 cycles (12 days) 48 are done; days 13, 14, 15 add 5, 4, 3 → 60 exactly on day 15.","type":"mcq","options":[{"k":"A","t":"13"},{"k":"B","t":"14"},{"k":"C","t":"15"},{"k":"D","t":"16"}],"answer":"C"},{"id":"fs-q4-5","topic":"qa-alg","difficulty":"medium","src":"final","stem":"What is the value of [1/4] + [2/4] + [3/4] + … + [30/4], where [x] is the greatest integer function?","explanation":"Each value 1 to 6 appears 4 times (4–7 give 1, …, 24–27 give 6) and 28, 29, 30 give 7. Sum = 4 × 21 + 21 = 105.","type":"tita","answer":"105","numeric":true},{"id":"fs-q4-6","topic":"qa-arith","difficulty":"easy","src":"final","stem":"What single discount is equivalent to successive discounts of 20% and 10%?","explanation":"0.8 × 0.9 = 0.72 → 28% off.","type":"mcq","options":[{"k":"A","t":"32%"},{"k":"B","t":"28%"},{"k":"C","t":"30%"},{"k":"D","t":"27%"}],"answer":"B"},{"id":"fs-q4-7","topic":"qa-alg","difficulty":"medium","src":"final","stem":"If α and β are the roots of 2x² − 5x + 1 = 0, what is α³ + β³?","explanation":"α + β = 5/2, αβ = 1/2. α³ + β³ = (α + β)³ − 3αβ(α + β) = 125/8 − 15/4 = 95/8.","type":"mcq","options":[{"k":"A","t":"105/8"},{"k":"B","t":"125/8"},{"k":"C","t":"95/8"},{"k":"D","t":"85/8"}],"answer":"C"},{"id":"fs-q4-8","topic":"qa-arith","difficulty":"medium","src":"final","stem":"A shopkeeper uses an 800 g weight in place of 1 kg and sells at 10% above the cost price. What is his actual profit percentage?","explanation":"He charges 1.1 × the cost of 1 kg for goods costing 0.8 of it: 1.1/0.8 = 1.375 → 37.5% profit.","type":"tita","answer":"37.5","numeric":true},{"id":"fs-q4-9","topic":"qa-alg","difficulty":"easy","src":"final","stem":"The 4th term of an AP is 14 and the 10th term is 32. What is the 25th term?","explanation":"6d = 18 → d = 3, a = 5. T₂₅ = 5 + 24 × 3 = 77.","type":"tita","answer":"77","numeric":true},{"id":"fs-q4-10","topic":"qa-arith","difficulty":"medium","src":"final","stem":"Two people start at the same time from P and Q towards each other. After meeting, one takes 9 hours to reach Q and the other 16 hours to reach P. How many hours does the faster one take for the whole journey?","explanation":"They meet after √(9 × 16) = 12 hours. The faster one needs only 9 more hours after meeting: 12 + 9 = 21.","type":"mcq","options":[{"k":"A","t":"21"},{"k":"B","t":"24"},{"k":"C","t":"25"},{"k":"D","t":"28"}],"answer":"A"},{"id":"fs-q4-11","topic":"qa-alg","difficulty":"easy","src":"final","stem":"How many integers n satisfy n² − 10n + 21 < 0?","explanation":"(n − 3)(n − 7) < 0 → 3 < n < 7 → n = 4, 5, 6.","type":"mcq","options":[{"k":"A","t":"2"},{"k":"B","t":"3"},{"k":"C","t":"4"},{"k":"D","t":"5"}],"answer":"B"},{"id":"fs-q4-12","topic":"qa-arith","difficulty":"easy","src":"final","stem":"The average weight of 8 people rises by 2.5 kg when one of them, weighing 56 kg, is replaced by a new person. What does the new person weigh, in kg?","explanation":"Total rises by 8 × 2.5 = 20, so the new person is 56 + 20 = 76 kg.","type":"tita","answer":"76","numeric":true},{"id":"fs-q4-13","topic":"qa-mod","difficulty":"hard","src":"final","stem":"How many three-digit numbers have digits that add up to 10?","explanation":"Write a = 1 + a′: a′ + b + c = 9 has C(11, 2) = 55 solutions; remove a′ = 9 (a = 10): 54.\nSignal: digit-sum condition (2021 S2, 2025 S3). Stars and bars, then remove impossible digits.","type":"tita","answer":"54","numeric":true},{"id":"fs-q4-14","topic":"qa-alg","difficulty":"medium","src":"final","stem":"Real numbers x and y satisfy x² + y² = 25 and x + y = 7. What is x³ + y³?","explanation":"xy = (49 − 25)/2 = 12. x³ + y³ = 7³ − 3 × 12 × 7 = 91.","type":"mcq","options":[{"k":"A","t":"85"},{"k":"B","t":"91"},{"k":"C","t":"97"},{"k":"D","t":"133"}],"answer":"B"},{"id":"fs-q4-15","topic":"qa-arith","difficulty":"medium","src":"final","stem":"Vessel A has milk and water in the ratio 3 : 1 and vessel B in the ratio 5 : 3. In what ratio must A and B be mixed to get milk and water in the ratio 2 : 1?","explanation":"Milk fractions 3/4, 5/8, target 2/3. A : B = (2/3 − 5/8) : (3/4 − 2/3) = 1/24 : 1/12 = 1 : 2.","type":"mcq","options":[{"k":"A","t":"1 : 3"},{"k":"B","t":"2 : 1"},{"k":"C","t":"2 : 3"},{"k":"D","t":"1 : 2"}],"answer":"D"},{"id":"fs-q4-16","topic":"qa-alg","difficulty":"easy","src":"final","stem":"A function satisfies f(x + y) = f(x)·f(y) for all x, y, and f(1) = 3. What is f(5)?","explanation":"f(n) = f(1)ⁿ = 3⁵ = 243.","type":"mcq","options":[{"k":"A","t":"15"},{"k":"B","t":"81"},{"k":"C","t":"125"},{"k":"D","t":"243"}],"answer":"D"},{"id":"fs-q4-17","topic":"qa-geo","difficulty":"medium","src":"final","stem":"Two circles of radii 9 cm and 4 cm touch each other externally. What is the length of their direct common tangent?","explanation":"Direct common tangent = √(d² − (r₁ − r₂)²) = √(169 − 25) = 12 (= 2√(r₁r₂) when the circles touch).","type":"mcq","options":[{"k":"A","t":"13 cm"},{"k":"B","t":"12 cm"},{"k":"C","t":"10 cm"},{"k":"D","t":"6√2 cm"}],"answer":"B"},{"id":"fs-q4-18","topic":"qa-geo","difficulty":"medium","src":"final","stem":"In triangle ABC of area 100 cm², D lies on BC with BD : DC = 2 : 3, and E is the midpoint of AD. What is the area of triangle BED, in cm²?","explanation":"Triangle ABD = 2/5 × 100 = 40. E halves AD, so BED = 20.","type":"tita","answer":"20","numeric":true},{"id":"fs-q4-19","topic":"qa-num","difficulty":"easy","src":"final","stem":"How many positive factors does 720 have?","explanation":"720 = 2⁴ × 3² × 5 → 5 × 3 × 2 = 30.","type":"tita","answer":"30","numeric":true},{"id":"fs-q4-20","topic":"qa-geo","difficulty":"medium","src":"final","stem":"What is the distance between the parallel lines 3x + 4y = 12 and 6x + 8y = 9?","explanation":"Rewrite the second as 3x + 4y = 4.5. Distance = |12 − 4.5|/√(9 + 16) = 1.5.","type":"mcq","options":[{"k":"A","t":"0.6"},{"k":"B","t":"1.5"},{"k":"C","t":"2.1"},{"k":"D","t":"3"}],"answer":"B"},{"id":"fs-q4-21","topic":"qa-num","difficulty":"hard","src":"final","stem":"What is the remainder when 17²³ + 23¹⁷ is divided by 20?","explanation":"17 ≡ −3 and 23 ≡ 3 (mod 20), and 3⁴ = 81 ≡ 1. 17²³ ≡ −3²³ = −3³ ≡ −27 ≡ −7. 23¹⁷ ≡ 3¹⁷ ≡ 3. Sum ≡ −4 ≡ 16.","type":"mcq","options":[{"k":"A","t":"0"},{"k":"B","t":"4"},{"k":"C","t":"10"},{"k":"D","t":"16"}],"answer":"D"},{"id":"fs-q4-22","topic":"qa-mod","difficulty":"easy","src":"final","stem":"In how many ways can the letters of the word LETTER be arranged?","explanation":"6!/(2! × 2!) = 180 (two E's, two T's).","type":"mcq","options":[{"k":"A","t":"90"},{"k":"B","t":"180"},{"k":"C","t":"360"},{"k":"D","t":"720"}],"answer":"B"},{"id":"fs-d1-1-1","topic":"dilr","passage":"fs-d1-s1","difficulty":"easy","src":"final","stem":"Which outlet earned the highest total revenue over the three months?","explanation":"Revenue (₹ lakh) Jan/Feb/Mar: A 10.00/10.56/11.50 = 32.06; B 11.00/11.00/12.60 = 34.60; C 9.60/10.80/10.23 = 30.63; D 11.16/11.02/12.25 = 34.43; E 7.00/8.10/10.40 = 25.50. B just beats D.\nSet signal: a pure calculation table with no hidden structure — the set to open first.","type":"mcq","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B"},{"id":"fs-d1-1-2","topic":"dilr","passage":"fs-d1-s1","difficulty":"easy","src":"final","stem":"In how many outlets did the revenue rise in both February and March (each month higher than the month before)?","explanation":"A (10.00 → 10.56 → 11.50) and E (7.00 → 8.10 → 10.40). B stays flat in February, C falls in March and D falls in February.","type":"tita","answer":"2","numeric":true},{"id":"fs-d1-1-3","topic":"dilr","passage":"fs-d1-s1","difficulty":"easy","src":"final","stem":"What was the total revenue of the chain in March, in ₹ lakh?","explanation":"11.50 + 12.60 + 10.23 + 12.25 + 10.40 = 56.98.","type":"tita","answer":"56.98","numeric":true},{"id":"fs-d1-1-4","topic":"dilr","passage":"fs-d1-s1","difficulty":"easy","src":"final","stem":"Which outlet had the highest percentage growth in revenue from January to March?","explanation":"Growth: A 15%, B 14.5%, D 9.8%, E 48.6% (7.00 → 10.40).","type":"mcq","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"D"},{"k":"D","t":"E"}],"answer":"D"},{"id":"fs-d1-1-5","topic":"dilr","passage":"fs-d1-s1","difficulty":"easy","src":"final","stem":"In how many of the 15 outlet-months was the revenue more than ₹11 lakh?","explanation":"A-Mar 11.50, B-Mar 12.60, D-Jan 11.16, D-Feb 11.02, D-Mar 12.25. B's 11.00 in Jan and Feb is not more than 11.","type":"tita","answer":"5","numeric":true},{"id":"fs-d1-2-1","topic":"dilr","passage":"fs-d1-s2","difficulty":"medium","src":"final","stem":"If G speaks on Wednesday, who speaks on Thursday afternoon?","explanation":"Clue 2 + 4 + 3 fill Monday with C, B. E–D must be a morning–afternoon pair on Wednesday or Thursday. If G takes Wednesday morning, E–D is Thursday, and H takes Wednesday afternoon. Thursday afternoon = D.\nSet key: there are only 4 complete schedules (Tuesday = A/F in either order × E–D on Wednesday or Thursday).","type":"mcq","options":[{"k":"A","t":"D"},{"k":"B","t":"E"},{"k":"C","t":"F"},{"k":"D","t":"H"}],"answer":"A"},{"id":"fs-d1-2-2","topic":"dilr","passage":"fs-d1-s2","difficulty":"medium","src":"final","stem":"If A speaks in the morning and D speaks on Wednesday, who speaks on Thursday morning?","explanation":"A Tuesday morning → F Tuesday afternoon. E–D on Wednesday, so Thursday has G (morning, clue 5) and H (afternoon).","type":"mcq","options":[{"k":"A","t":"E"},{"k":"B","t":"F"},{"k":"C","t":"G"},{"k":"D","t":"H"}],"answer":"C"},{"id":"fs-d1-2-3","topic":"dilr","passage":"fs-d1-s2","difficulty":"medium","src":"final","stem":"Which of the following must be true?","explanation":"Monday is B/C and A is on Tuesday. F must be on an earlier day than G (Wednesday or Thursday) and cannot be on Monday, so F is A's partner on Tuesday in every schedule. The other three fail in at least one schedule.","type":"mcq","options":[{"k":"A","t":"H speaks on Thursday"},{"k":"B","t":"F speaks on Tuesday"},{"k":"C","t":"E speaks on Wednesday"},{"k":"D","t":"G speaks before E"}],"answer":"B"},{"id":"fs-d1-2-4","topic":"dilr","passage":"fs-d1-s2","difficulty":"medium","src":"final","stem":"How many different complete schedules satisfy all the conditions?","explanation":"Tuesday: A and F in either order (2 ways). Then E–D and G–H fill Wednesday and Thursday with E and G in the mornings: E–D on Wednesday or Thursday (2 ways). 2 × 2 = 4.","type":"tita","answer":"4","numeric":true},{"id":"fs-d1-3-1","topic":"dilr","passage":"fs-d1-s3","difficulty":"hard","src":"final","stem":"If R finished with an even number of points, how many points did S finish with?","explanation":"Total points = 30 − 3 draws = 27. P (10) = 3 wins + the draw with S; T's single point is a draw. Q + R + S = 16 with Q > R > S. Working through who drew with T leaves two tables: Q 9, R 4, S 3 or Q 7, R 6, S 3. S has 3 either way.\nSet signal: points tables reward the 'total points = 3 × matches − draws' check first.","type":"tita","answer":"3","numeric":true},{"id":"fs-d1-3-2","topic":"dilr","passage":"fs-d1-s3","difficulty":"hard","src":"final","stem":"Which match ended in a draw?","explanation":"T's only point must come from a draw, and R beat T, P beat T. In both possible tables T's draw is with S.","type":"mcq","options":[{"k":"A","t":"R vs S"},{"k":"B","t":"Q vs S"},{"k":"C","t":"Q vs R"},{"k":"D","t":"S vs T"}],"answer":"D"},{"id":"fs-d1-3-3","topic":"dilr","passage":"fs-d1-s3","difficulty":"hard","src":"final","stem":"What is the highest number of points Q could have finished with?","explanation":"Q 9 is possible (Q beats R, S and T and loses to P). Q cannot win all four because P won three of its matches and drew only with S.","type":"tita","answer":"9","numeric":true},{"id":"fs-d1-3-4","topic":"dilr","passage":"fs-d1-s3","difficulty":"hard","src":"final","stem":"If Q drew with S, how many points did R finish with?","explanation":"Q–S drawn means the three draws are P–S, Q–S and S–T. Then R beat S and T and lost to P and Q: 6 points.","type":"mcq","options":[{"k":"A","t":"4"},{"k":"B","t":"5"},{"k":"C","t":"6"},{"k":"D","t":"7"}],"answer":"C"},{"id":"fs-d1-4-1","topic":"dilr","passage":"fs-d1-s4","difficulty":"medium","src":"final","stem":"What number is on the centre locker?","explanation":"Corners are even, so the middle row (three odd numbers) = 17 and the top row = even + odd + even. Trying the corners leaves only two grids: 4 1 8 / 3 9 5 / 6 7 2 and 4 3 6 / 1 9 7 / 8 5 2. Centre = 9 in both.\nSet signal: parity (odd/even) kills most cases at once.","type":"tita","answer":"9","numeric":true},{"id":"fs-d1-4-2","topic":"dilr","passage":"fs-d1-s4","difficulty":"medium","src":"final","stem":"What number is on the bottom-right locker?","explanation":"Both grids have 2 in the bottom-right corner.","type":"mcq","options":[{"k":"A","t":"2"},{"k":"B","t":"4"},{"k":"C","t":"6"},{"k":"D","t":"8"}],"answer":"A"},{"id":"fs-d1-4-3","topic":"dilr","passage":"fs-d1-s4","difficulty":"medium","src":"final","stem":"If the locker directly below the top-left one shows 3, what is the sum of the bottom row?","explanation":"That is the grid 4 1 8 / 3 9 5 / 6 7 2: bottom row 6 + 7 + 2 = 15.","type":"tita","answer":"15","numeric":true},{"id":"fs-d1-4-4","topic":"dilr","passage":"fs-d1-s4","difficulty":"medium","src":"final","stem":"Which of these could be the number on the top-middle locker?","explanation":"The top-middle locker is 1 or 3 in the two grids; of the options only 1 is possible.","type":"mcq","options":[{"k":"A","t":"1"},{"k":"B","t":"5"},{"k":"C","t":"7"},{"k":"D","t":"9"}],"answer":"A"},{"id":"fs-d1-5-1","topic":"dilr","passage":"fs-d1-s5","difficulty":"hard","src":"final","stem":"Who is the third friend to go out?","explanation":"Round 1: 1 passes 1 place → 2 out, ball to 3. Round 2: 2 places from 3 → 5 out, ball to 6. Round 3: 3 places from 6 (7, 1, 3) → 3 out.\nSet signal: rule games are slow but certain — write the circle once and cross people off.","type":"mcq","options":[{"k":"A","t":"1"},{"k":"B","t":"3"},{"k":"C","t":"4"},{"k":"D","t":"5"}],"answer":"B"},{"id":"fs-d1-5-2","topic":"dilr","passage":"fs-d1-s5","difficulty":"hard","src":"final","stem":"Who wins the game?","explanation":"Order out: 2, 5, 3, 4, 1, 6. Friend 7 is left.","type":"tita","answer":"7","numeric":true},{"id":"fs-d1-5-3","topic":"dilr","passage":"fs-d1-s5","difficulty":"hard","src":"final","stem":"In which round does friend 1 go out?","explanation":"From the order 2, 5, 3, 4, 1, 6, friend 1 is fifth out — round 5.","type":"tita","answer":"5","numeric":true},{"id":"fs-d1-5-4","topic":"dilr","passage":"fs-d1-s5","difficulty":"hard","src":"final","stem":"If the ball had started with friend 3 instead (same rules, 7 friends), who would win?","explanation":"Order out: 4, 7, 5, 6, 3, 1. Friend 2 wins. (Shifting the start does not simply shift the winner, because the pass lengths change each round.)","type":"mcq","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"6"},{"k":"D","t":"7"}],"answer":"B"},{"id":"fs-d1-5-5","topic":"dilr","passage":"fs-d1-s5","difficulty":"hard","src":"final","stem":"If there were 8 friends (numbered 1 to 8) and the ball started with friend 1, who would be the fourth friend to go out?","explanation":"Order out: 2, 5, 1, 8, … — the fourth is 8.","type":"tita","answer":"8","numeric":true},{"id":"fs-d2-1-1","topic":"dilr","passage":"fs-d2-s1","difficulty":"easy","src":"final","stem":"Which route carried the third-highest number of passengers in the week?","explanation":"Passengers: R1 10,710, R2 8,064, R3 5,670, R4 3,780, R5 2,940.\nSet signal: one formula applied row by row — open this set first.","type":"mcq","options":[{"k":"A","t":"R3"},{"k":"B","t":"R5"},{"k":"C","t":"R4"},{"k":"D","t":"R2"}],"answer":"A"},{"id":"fs-d2-1-2","topic":"dilr","passage":"fs-d2-s1","difficulty":"easy","src":"final","stem":"What was the airline's total revenue from the five routes in the week, to the nearest ₹ lakh?","explanation":"Revenue: R1 5,56,92,000; R2 4,91,90,400; R3 2,43,81,000; R4 2,57,04,000; R5 94,08,000. Total ₹16,43,75,400 ≈ 1,644 lakh.","type":"tita","answer":"1644","numeric":true},{"id":"fs-d2-1-3","topic":"dilr","passage":"fs-d2-s1","difficulty":"easy","src":"final","stem":"Revenue per seat offered (filled or not) = load factor × average fare. On which route is it highest?","explanation":"R1 0.85 × 5,200 = 4,420; R2 4,880; R3 3,870; R4 0.75 × 6,800 = 5,100.","type":"mcq","options":[{"k":"A","t":"R2"},{"k":"B","t":"R1"},{"k":"C","t":"R3"},{"k":"D","t":"R4"}],"answer":"D"},{"id":"fs-d2-1-4","topic":"dilr","passage":"fs-d2-s1","difficulty":"easy","src":"final","stem":"On how many routes was the weekly revenue more than ₹2.5 crore?","explanation":"R1 5.57, R2 4.92, R4 2.57 crore. R3 (2.44) and R5 (0.94) fall short.","type":"tita","answer":"3","numeric":true},{"id":"fs-d2-1-5","topic":"dilr","passage":"fs-d2-s1","difficulty":"easy","src":"final","stem":"The airline adds 14 weekly flights on R5, and R5's load factor falls to 60%. By how many passengers per week does R5's traffic rise?","explanation":"New: 49 × 120 × 0.60 = 3,528. Old: 2,940. Rise = 588.","type":"tita","answer":"588","numeric":true},{"id":"fs-d2-2-1","topic":"dilr","passage":"fs-d2-s2","difficulty":"easy","src":"final","stem":"Who is on duty on Tuesday?","explanation":"Friday's neurologist is not D, B (ortho) or E (Monday), and A must follow the dermatologist, so C is on Friday. B is before C and is not the Wednesday cardiologist, so B is Thursday. A follows the dermatologist: E (Monday) is the dermatologist and A is Tuesday; D is the Wednesday cardiologist; A is ENT.\nSet signal: a single fixed day plus 'day after' clue → unique grid. Fast marks.","type":"mcq","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A"},{"id":"fs-d2-2-2","topic":"dilr","passage":"fs-d2-s2","difficulty":"easy","src":"final","stem":"What is D's speciality?","explanation":"D is on Wednesday, the cardiologist's day.","type":"mcq","options":[{"k":"A","t":"Cardiology"},{"k":"B","t":"Dermatology"},{"k":"C","t":"Neurology"},{"k":"D","t":"ENT"}],"answer":"A"},{"id":"fs-d2-2-3","topic":"dilr","passage":"fs-d2-s2","difficulty":"easy","src":"final","stem":"On which day is the orthopaedist on duty? Type 1 for Monday, 2 for Tuesday, and so on.","explanation":"B is the orthopaedist and is on Thursday.","type":"tita","answer":"4","numeric":true},{"id":"fs-d2-2-4","topic":"dilr","passage":"fs-d2-s2","difficulty":"easy","src":"final","stem":"Which pair is correctly matched?","explanation":"C is the Friday neurologist.","type":"mcq","options":[{"k":"A","t":"A – Dermatology"},{"k":"B","t":"C – Neurology"},{"k":"C","t":"E – ENT"},{"k":"D","t":"B – Cardiology"}],"answer":"B"},{"id":"fs-d2-3-1","topic":"dilr","passage":"fs-d2-s3","difficulty":"hard","src":"final","stem":"What rating did Y receive on day 3?","explanation":"Totals: X days 1–2 = 7, days 3–4 = 7, day 5 = 4. Y days 1–3 = 9, day 4 = 4. Y's day 5 beats every earlier rating, so it is 5. With X's day 3 < day 4 we get X = 2, 5 on days 3–4, and working the 'different every day / X wins three days' clues leaves X = (2,5,2,5,4) with Y = (1,4,4,4,5), or X = (3,4,2,5,4) with Y = (2,3,4,4,5). Y's day 3 = 4 either way.\nSet signal: convert every average into a running total first.","type":"tita","answer":"4","numeric":true},{"id":"fs-d2-3-2","topic":"dilr","passage":"fs-d2-s3","difficulty":"hard","src":"final","stem":"What was Y's average rating over the five days?","explanation":"Y's total is 18 in both cases (13 + 5): 18/5 = 3.6.","type":"tita","answer":"3.6","numeric":true},{"id":"fs-d2-3-3","topic":"dilr","passage":"fs-d2-s3","difficulty":"hard","src":"final","stem":"On which day were the two products' running averages equal for the first time?","explanation":"Case 1: X 2, 3.5, 3 … and Y 1, 2.5, 3 … Case 2: X 3, 3.5, 3 … and Y 2, 2.5, 3 … Both meet at 3 on day 3.","type":"tita","answer":"3","numeric":true},{"id":"fs-d2-3-4","topic":"dilr","passage":"fs-d2-s3","difficulty":"hard","src":"final","stem":"If X's day-1 rating was 3, what was Y's day-2 rating?","explanation":"X day 1 = 3 is case 2: Y = (2, 3, 4, 4, 5).","type":"mcq","options":[{"k":"A","t":"2"},{"k":"B","t":"3"},{"k":"C","t":"4"},{"k":"D","t":"5"}],"answer":"B"},{"id":"fs-d2-4-1","topic":"dilr","passage":"fs-d2-s4","difficulty":"medium","src":"final","stem":"What is the length of the shortest route from A to F, in km?","explanation":"Candidates: A–C–D–E–F = 25 + 35 + 20 + 25 = 105; A–C–E–F = 110; A–C–D–F and A–B–D–E–F = 115; A–B–D–F = 125; A–B–F = 130.\nSet signal: small networks — list all routes once, then every question is a lookup.","type":"tita","answer":"105","numeric":true},{"id":"fs-d2-4-2","topic":"dilr","passage":"fs-d2-s4","difficulty":"medium","src":"final","stem":"A driver wants to pay the least toll on a route from A to F that is at most 120 km long. Which route should she take?","explanation":"Tolls on routes ≤ 120 km: A–C–D–E–F ₹120, A–C–E–F ₹90, A–B–D–E–F ₹70, A–C–D–F ₹50.","type":"mcq","options":[{"k":"A","t":"A–B–D–E–F"},{"k":"B","t":"A–C–E–F"},{"k":"C","t":"A–C–D–E–F"},{"k":"D","t":"A–C–D–F"}],"answer":"D"},{"id":"fs-d2-4-3","topic":"dilr","passage":"fs-d2-s4","difficulty":"medium","src":"final","stem":"If the road D–E is closed, what is the shortest distance from A to F?","explanation":"Without D–E: A–C–E–F = 110 is the shortest.","type":"mcq","options":[{"k":"A","t":"115 km"},{"k":"B","t":"110 km"},{"k":"C","t":"120 km"},{"k":"D","t":"125 km"}],"answer":"B"},{"id":"fs-d2-4-4","topic":"dilr","passage":"fs-d2-s4","difficulty":"medium","src":"final","stem":"Fuel costs ₹8 per km. What is the lowest total cost (fuel + tolls) of driving from A to F, in ₹?","explanation":"A–C–D–E–F: 105 × 8 + 120 = 960. Next best: A–C–D–F and A–C–E–F at 970, A–B–D–E–F at 990.","type":"tita","answer":"960","numeric":true},{"id":"fs-d2-5-1","topic":"dilr","passage":"fs-d2-s5","difficulty":"medium","src":"final","stem":"Who gives in round 3?","explanation":"After round 1: 10, 10, 6, 4. Round 2: A (tie, alphabetical) gives → 7, 11, 7, 5. Round 3: B has the most.\nSet signal: simulate and look for a repeating cycle.","type":"mcq","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B"},{"id":"fs-d2-5-2","topic":"dilr","passage":"fs-d2-s5","difficulty":"medium","src":"final","stem":"How many coins does D have after round 6?","explanation":"Rounds 3–6 give 8,8,8,6 → 5,9,9,7 → 6,6,10,8 → 7,7,7,9. D has 9.","type":"tita","answer":"9","numeric":true},{"id":"fs-d2-5-3","topic":"dilr","passage":"fs-d2-s5","difficulty":"medium","src":"final","stem":"In which round does D give for the first time?","explanation":"After round 6, D has 9, the most, so D gives in round 7.","type":"tita","answer":"7","numeric":true},{"id":"fs-d2-5-4","topic":"dilr","passage":"fs-d2-s5","difficulty":"medium","src":"final","stem":"How many coins does C have after round 50?","explanation":"From round 3 the state repeats every 4 rounds: after rounds 3, 7, 11, … C has 8; after 4, 8, … 9; after 5, 9, … 10; after 6, 10, … 7. Round 50 is in the last group: 7.","type":"mcq","options":[{"k":"A","t":"7"},{"k":"B","t":"8"},{"k":"C","t":"9"},{"k":"D","t":"10"}],"answer":"A"},{"id":"fs-d2-5-5","topic":"dilr","passage":"fs-d2-s5","difficulty":"medium","src":"final","stem":"In the first 20 rounds, how many times does A give?","explanation":"A gives in rounds 1, 2, 4, 8, 12, 16 and 20.","type":"tita","answer":"7","numeric":true},{"id":"fs-d3-1-1","topic":"dilr","passage":"fs-d3-s1","difficulty":"medium","src":"final","stem":"What was H1's bill for Q3, in ₹?","explanation":"410 units: 150 + 100 × 4 + 200 × 6 + 110 × 8 = 150 + 400 + 1,200 + 880 = 2,630.\nSet signal: slab bills — pre-compute 'cost of 300 units' (₹1,750 with the fixed charge) and add ₹8 per extra unit.","type":"tita","answer":"2630","numeric":true},{"id":"fs-d3-1-2","topic":"dilr","passage":"fs-d3-s1","difficulty":"medium","src":"final","stem":"Which household had the third-highest total bill for the year?","explanation":"Annual bills: H4 9,640, H1 7,620, H5 7,060, H2 4,840, H3 2,560.","type":"mcq","options":[{"k":"A","t":"H1"},{"k":"B","t":"H3"},{"k":"C","t":"H5"},{"k":"D","t":"H2"}],"answer":"C"},{"id":"fs-d3-1-3","topic":"dilr","passage":"fs-d3-s1","difficulty":"medium","src":"final","stem":"In how many of the 20 household-quarters did consumption go above 300 units?","explanation":"H1: 320, 410; H4: all four; H5: 310 and 305. H5's 300 in Q1 is not above 300. Total 8.","type":"tita","answer":"8","numeric":true},{"id":"fs-d3-1-4","topic":"dilr","passage":"fs-d3-s1","difficulty":"medium","src":"final","stem":"If the rate above 300 units rises from ₹8 to ₹10, by how much does H4's annual bill rise?","explanation":"H4's units above 300: 40 + 80 + 150 + 60 = 330. Extra ₹2 each = ₹660.","type":"mcq","options":[{"k":"A","t":"₹660"},{"k":"B","t":"₹600"},{"k":"C","t":"₹720"},{"k":"D","t":"₹540"}],"answer":"A"},{"id":"fs-d3-1-5","topic":"dilr","passage":"fs-d3-s1","difficulty":"medium","src":"final","stem":"H2 and H3 decide to share one connection, paying one fixed charge on their combined units each quarter. Compared with paying separately, what happens to their total bill for the year?","explanation":"Combined units 270, 330, 410, 285 → bills 1,570 + 1,990 + 2,630 + 1,660 = 7,850. Separately: 4,840 + 2,560 = 7,400. The saved fixed charges (₹600) are outweighed by the higher slabs: +₹450.","type":"mcq","options":[{"k":"A","t":"It rises by ₹450"},{"k":"B","t":"It falls by ₹450"},{"k":"C","t":"It rises by ₹300"},{"k":"D","t":"It falls by ₹600"}],"answer":"A"},{"id":"fs-d3-2-1","topic":"dilr","passage":"fs-d3-s2","difficulty":"easy","src":"final","stem":"Who stands at position 2?","explanation":"Positions 4, 5, 7 are C, D, G. A and B are 3 apart among 1, 2, 3, 6 → A = 3, B = 6. E ahead of F → E = 1, F = 2. Professions: front (E) lawyer; doctors not adjacent with G (7) a doctor → doctors at 2, 4, 7 (F, C, G); B is the other engineer (must be behind A); A is a lawyer.\nSet signal: fixed positions first, then the 'gap' clue — unique answer.","type":"mcq","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"E"},{"k":"D","t":"F"}],"answer":"D"},{"id":"fs-d3-2-2","topic":"dilr","passage":"fs-d3-s2","difficulty":"easy","src":"final","stem":"How many lawyers stand ahead of C?","explanation":"Lawyers are E (1) and A (3), both ahead of C (4).","type":"tita","answer":"2","numeric":true},{"id":"fs-d3-2-3","topic":"dilr","passage":"fs-d3-s2","difficulty":"easy","src":"final","stem":"What is A's profession?","explanation":"See the arrangement above.","type":"mcq","options":[{"k":"A","t":"Lawyer"},{"k":"B","t":"Cannot be determined"},{"k":"C","t":"Doctor"},{"k":"D","t":"Engineer"}],"answer":"A"},{"id":"fs-d3-2-4","topic":"dilr","passage":"fs-d3-s2","difficulty":"easy","src":"final","stem":"At which position does the second doctor from the front stand?","explanation":"Doctors at 2, 4 and 7.","type":"tita","answer":"4","numeric":true},{"id":"fs-d3-3-1","topic":"dilr","passage":"fs-d3-s3","difficulty":"medium","src":"final","stem":"What was Y's total?","explanation":"X = 22 needs 8 + 8 + 6 or 8 + 7 + 7; X can't have 8 in Test 1 (W has it), so X scored 8 in Tests 2 and 3 and 6 in Test 1. W is the lowest, so W scored 5 in Tests 2 and 3 (total 18). Y's equal marks in Tests 2 and 3 must be 6 or 7; Z's Test 3 beats Z's Test 1. This forces Y = 7, 6, 6 and Z = 5, 7, 7. Y's total = 19.\nSet signal: in 'each test is a permutation' sets, the extreme totals pin the 8s and 5s.","type":"tita","answer":"19","numeric":true},{"id":"fs-d3-3-2","topic":"dilr","passage":"fs-d3-s3","difficulty":"medium","src":"final","stem":"Who scored 7 in Test 1?","explanation":"Test 1: W 8, X 6, Y 7, Z 5.","type":"mcq","options":[{"k":"A","t":"X"},{"k":"B","t":"Y"},{"k":"C","t":"W"},{"k":"D","t":"Z"}],"answer":"B"},{"id":"fs-d3-3-3","topic":"dilr","passage":"fs-d3-s3","difficulty":"medium","src":"final","stem":"Which of the following is true?","explanation":"Y = 19 and Z = 19.","type":"mcq","options":[{"k":"A","t":"W scored 6 in Test 3"},{"k":"B","t":"Z scored 8 in Test 2"},{"k":"C","t":"Y and Z had the same total"},{"k":"D","t":"X scored 8 in Test 1"}],"answer":"C"},{"id":"fs-d3-3-4","topic":"dilr","passage":"fs-d3-s3","difficulty":"medium","src":"final","stem":"How many students scored the same marks in Test 2 and Test 3?","explanation":"W 5/5, X 8/8, Y 6/6, Z 7/7 — all four.","type":"tita","answer":"4","numeric":true},{"id":"fs-d3-4-1","topic":"dilr","passage":"fs-d3-s4","difficulty":"medium","src":"final","stem":"Who lives in the East flat on floor 1?","explanation":"A and B are a West pair on floors 3/2 or 4/3 (B not on 1). D–E need a whole floor; floor 1 is the only floor left whole in both cases, so D = 1-West, E = 1-East, and F = 2-East. Two buildings remain: (2W B, 3W A, 3E H, 4W G) or (2W H, 3W B, 3E G, 4W A).\nSet signal: a pair that needs a whole floor (D–E) is the first thing to place.","type":"mcq","options":[{"k":"A","t":"D"},{"k":"B","t":"E"},{"k":"C","t":"F"},{"k":"D","t":"H"}],"answer":"B"},{"id":"fs-d3-4-2","topic":"dilr","passage":"fs-d3-s4","difficulty":"medium","src":"final","stem":"On which floor does F live?","explanation":"F is in 2-East in both buildings.","type":"tita","answer":"2","numeric":true},{"id":"fs-d3-4-3","topic":"dilr","passage":"fs-d3-s4","difficulty":"medium","src":"final","stem":"If G lives on the top floor, who lives directly below A?","explanation":"G on floor 4 is the first building: A in 3-West, B in 2-West directly below.","type":"mcq","options":[{"k":"A","t":"B"},{"k":"B","t":"D"},{"k":"C","t":"F"},{"k":"D","t":"H"}],"answer":"A"},{"id":"fs-d3-4-4","topic":"dilr","passage":"fs-d3-s4","difficulty":"medium","src":"final","stem":"For how many of the eight families can the flat be fixed exactly?","explanation":"C (4-East), D (1-West), E (1-East) and F (2-East). A, B, G and H change between the two buildings.","type":"tita","answer":"4","numeric":true},{"id":"fs-d3-5-1","topic":"dilr","passage":"fs-d3-s5","difficulty":"hard","src":"final","stem":"Who buys painting Y?","explanation":"W: Q wins (50), pays P's 45 → Q has 25. X: R wins (70), pays P's 60 → R has 15. Y: Q (65) and R (30) can't afford it; S (60) beats P (50) and pays 50.\nSet signal: rule sets look long but every question is a simulation — budget the time, not the thinking.","type":"mcq","options":[{"k":"A","t":"Q"},{"k":"B","t":"P"},{"k":"C","t":"S"},{"k":"D","t":"T"}],"answer":"C"},{"id":"fs-d3-5-2","topic":"dilr","passage":"fs-d3-s5","difficulty":"hard","src":"final","stem":"What is the total amount collected for the four paintings, in ₹ lakh?","explanation":"45 + 60 + 50 + 55 = 210 (Z goes to P, who pays T's 55).","type":"tita","answer":"210","numeric":true},{"id":"fs-d3-5-3","topic":"dilr","passage":"fs-d3-s5","difficulty":"hard","src":"final","stem":"How much does painting Z sell for, in ₹ lakh?","explanation":"Z: P (75) wins; T's 55 is the next highest among those who can afford their valuation.","type":"tita","answer":"55","numeric":true},{"id":"fs-d3-5-4","topic":"dilr","passage":"fs-d3-s5","difficulty":"hard","src":"final","stem":"If the paintings were auctioned in the order Z, Y, X, W, who would buy W?","explanation":"Z → P pays 55 (P left with 25). Y → Q pays 60 (Q has 10). X → R pays 50 (R has 25). W: P, Q, R can no longer afford their valuations; S (35) beats T (30).","type":"mcq","options":[{"k":"A","t":"P"},{"k":"B","t":"T"},{"k":"C","t":"S"},{"k":"D","t":"Q"}],"answer":"C"},{"id":"fs-d3-5-5","topic":"dilr","passage":"fs-d3-s5","difficulty":"hard","src":"final","stem":"In the order Z, Y, X, W, what is the total amount collected, in ₹ lakh?","explanation":"55 + 60 + 50 + 30 = 195.","type":"tita","answer":"195","numeric":true},{"id":"fs-d4-1-1","topic":"dilr","passage":"fs-d4-s1","difficulty":"easy","src":"final","stem":"Which stock gave the highest percentage return?","explanation":"Returns: A 16%, C 20%, D 10%, F 12%.\nSet signal: one-step arithmetic per row — open first.","type":"mcq","options":[{"k":"A","t":"A"},{"k":"B","t":"C"},{"k":"C","t":"D"},{"k":"D","t":"F"}],"answer":"B"},{"id":"fs-d4-1-2","topic":"dilr","passage":"fs-d4-s1","difficulty":"easy","src":"final","stem":"What was the trader's total profit before brokerage, in ₹?","explanation":"A +4,000, B −2,000, C +4,600, D +3,280, E −900, F +6,000 → 14,980.","type":"tita","answer":"14980","numeric":true},{"id":"fs-d4-1-3","topic":"dilr","passage":"fs-d4-s1","difficulty":"easy","src":"final","stem":"What was the total profit after brokerage, in ₹?","explanation":"Purchases ₹1,86,200 and sales ₹2,01,180 → brokerage 0.5% × 3,87,380 = 1,936.90. Profit = 14,980 − 1,936.90 = 13,043.10.","type":"tita","answer":"13043.1","numeric":true},{"id":"fs-d4-1-4","topic":"dilr","passage":"fs-d4-s1","difficulty":"easy","src":"final","stem":"For how many stocks was the profit larger than the brokerage paid on that stock?","explanation":"A (4,000 vs 270), C (4,600 vs 253), D (3,280 vs 344.40), F (6,000 vs 530). B and E made losses.","type":"mcq","options":[{"k":"A","t":"2"},{"k":"B","t":"3"},{"k":"C","t":"4"},{"k":"D","t":"5"}],"answer":"C"},{"id":"fs-d4-2-1","topic":"dilr","passage":"fs-d4-s2","difficulty":"medium","src":"final","stem":"Which team is F in?","explanation":"C is in Design; D and E fill a team that isn't Analytics or Design (it already has C) → Engineering. F is not in Design → Analytics. A and B take the remaining Design and Analytics places.\nSet signal: two-attribute grouping — fix the teams first, colleges second.","type":"mcq","options":[{"k":"A","t":"Cannot be determined"},{"k":"B","t":"Engineering"},{"k":"C","t":"Design"},{"k":"D","t":"Analytics"}],"answer":"D"},{"id":"fs-d4-2-2","topic":"dilr","passage":"fs-d4-s2","difficulty":"medium","src":"final","stem":"In how many different ways can the teams and colleges be assigned?","explanation":"A Design / B Analytics: A is IIT or BITS, and D/E are NIT + the remaining college in either order — 4 ways. A Analytics / B Design: A must be IIT (not BITS like F, not NIT), and D/E are NIT + BITS in either order — 2 ways. Total 6.","type":"tita","answer":"6","numeric":true},{"id":"fs-d4-2-3","topic":"dilr","passage":"fs-d4-s2","difficulty":"medium","src":"final","stem":"For how many interns are both the team and the college fixed?","explanation":"Only C (Design, NIT) and F (Analytics, BITS). B is always IIT but can be in Analytics or Design.","type":"tita","answer":"2","numeric":true},{"id":"fs-d4-2-4","topic":"dilr","passage":"fs-d4-s2","difficulty":"medium","src":"final","stem":"If E is from IIT, who is A's teammate?","explanation":"E from IIT happens only when A is in Design with C, A from BITS and D from NIT.","type":"mcq","options":[{"k":"A","t":"B"},{"k":"B","t":"C"},{"k":"C","t":"D"},{"k":"D","t":"F"}],"answer":"B"},{"id":"fs-d4-2-5","topic":"dilr","passage":"fs-d4-s2","difficulty":"medium","src":"final","stem":"Which of the following must be true?","explanation":"There are two NIT interns. One is C. A is not from NIT, B is from IIT and F is from BITS, so the other NIT intern must be D or E. The other options fail in at least one of the six assignments.","type":"mcq","options":[{"k":"A","t":"A is from IIT"},{"k":"B","t":"E is from BITS"},{"k":"C","t":"At least one of D and E is from NIT"},{"k":"D","t":"B is in Analytics"}],"answer":"C"},{"id":"fs-d4-3-1","topic":"dilr","passage":"fs-d4-s3","difficulty":"hard","src":"final","stem":"How many people use all three apps?","explanation":"190 use at least one. Counting app users: singles + 2 × (exactly two) + 3 × (all three) = 280, and singles + two + three = 190. Subtracting: two + 2 × three = 90 → three = 25.\nSet signal: the two equations 'people' and 'app memberships' solve most Venn sets.","type":"tita","answer":"25","numeric":true},{"id":"fs-d4-3-2","topic":"dilr","passage":"fs-d4-s3","difficulty":"hard","src":"final","stem":"How many people use exactly one app?","explanation":"190 − 40 − 25 = 125.","type":"tita","answer":"125","numeric":true},{"id":"fs-d4-3-3","topic":"dilr","passage":"fs-d4-s3","difficulty":"hard","src":"final","stem":"If 15 people use only N and P, and 10 use only P and H, how many use only N?","explanation":"Only N and H = 40 − 15 − 10 = 15. Only N = 110 − 15 − 15 − 25 = 55.","type":"mcq","options":[{"k":"A","t":"45"},{"k":"B","t":"50"},{"k":"C","t":"55"},{"k":"D","t":"60"}],"answer":"C"},{"id":"fs-d4-3-4","topic":"dilr","passage":"fs-d4-s3","difficulty":"hard","src":"final","stem":"What is the largest possible number of people who use only H?","explanation":"Only H = 80 − 25 − (N&H only) − (P&H only). Make both those zero: all 40 'exactly two' are N&P only; then only N = 45 and only P = 25, both valid. Only H = 55.","type":"mcq","options":[{"k":"A","t":"40"},{"k":"B","t":"45"},{"k":"C","t":"50"},{"k":"D","t":"55"}],"answer":"D"},{"id":"fs-d4-4-1","topic":"dilr","passage":"fs-d4-s4","difficulty":"medium","src":"final","stem":"Which crop grows in plot (4, 1)?","explanation":"Row 1 must be W R M P (rice can't be at (1,3) — column 3 has rice at (2,3)). Column 4 then needs rice at (3,4) (not (4,4), not (2,4) since row 2 has rice at (2,3)), so (4,4) is maize and (2,4) wheat. Column 1's rice can only go to (4,1). Three grids remain.\nSet signal: in Latin-square grids, chase one crop at a time through rows and columns.","type":"mcq","options":[{"k":"A","t":"Pulses"},{"k":"B","t":"Maize"},{"k":"C","t":"Wheat"},{"k":"D","t":"Rice"}],"answer":"D"},{"id":"fs-d4-4-2","topic":"dilr","passage":"fs-d4-s4","difficulty":"medium","src":"final","stem":"How many of the 16 plots have a crop that can be fixed for certain?","explanation":"Fixed: all of row 1 (4), (2,3), (2,4), (3,4), (4,1), (4,4) → 9.","type":"tita","answer":"9","numeric":true},{"id":"fs-d4-4-3","topic":"dilr","passage":"fs-d4-s4","difficulty":"medium","src":"final","stem":"If plot (2, 1) grows maize, which crop grows in plot (3, 3)?","explanation":"(2,1) maize → row 2 is M P R W, row 3 P M W R, row 4 R W P M. (3,3) = wheat.","type":"mcq","options":[{"k":"A","t":"Maize"},{"k":"B","t":"Pulses"},{"k":"C","t":"Rice"},{"k":"D","t":"Wheat"}],"answer":"D"},{"id":"fs-d4-4-4","topic":"dilr","passage":"fs-d4-s4","difficulty":"medium","src":"final","stem":"If plot (3, 2) grows pulses, which crop grows in plot (4, 3)?","explanation":"(3,2) pulses → row 3 is M P W R and row 4 R W P M. (4,3) = pulses.","type":"mcq","options":[{"k":"A","t":"Rice"},{"k":"B","t":"Wheat"},{"k":"C","t":"Maize"},{"k":"D","t":"Pulses"}],"answer":"D"},{"id":"fs-d4-5-1","topic":"dilr","passage":"fs-d4-s5","difficulty":"hard","src":"final","stem":"Who is served at counter 2 right after B?","explanation":"A takes counter 1 (0–6), B counter 2 (1–5). At minute 5, C (waiting since 2), D (senior, since 4) and E are waiting — D goes first, to counter 2 (5–8). C gets counter 1 at 6 (6–11), E counter 2 at 8 (8–15), G (senior) counter 1 at 11 (11–15), then F and H at 15.\nSet signal: draw a two-row timeline; the priority rule is the only trap.","type":"mcq","options":[{"k":"A","t":"C"},{"k":"B","t":"D"},{"k":"C","t":"E"},{"k":"D","t":"F"}],"answer":"B"},{"id":"fs-d4-5-2","topic":"dilr","passage":"fs-d4-s5","difficulty":"hard","src":"final","stem":"At what time (minutes after 10:00) does C's service begin?","explanation":"Counter 1 frees at 6 and C is next.","type":"tita","answer":"6","numeric":true},{"id":"fs-d4-5-3","topic":"dilr","passage":"fs-d4-s5","difficulty":"hard","src":"final","stem":"What is the total waiting time of the eight customers, in minutes?","explanation":"Waits: A 0, B 0, C 4, D 1, E 3, F 6, G 1, H 3 = 18.","type":"tita","answer":"18","numeric":true},{"id":"fs-d4-5-4","topic":"dilr","passage":"fs-d4-s5","difficulty":"hard","src":"final","stem":"How many customers wait 3 minutes or more?","explanation":"C (4), E (3), F (6), H (3).","type":"tita","answer":"4","numeric":true},{"id":"fs-d4-5-5","topic":"dilr","passage":"fs-d4-s5","difficulty":"hard","src":"final","stem":"If there were no priority for senior citizens, at what time would the last customer finish?","explanation":"Order by arrival: C at 5 (counter 2), D at 6, E at 9, F at 10, G at 12, H at 16 on counter 1 → finishes at 19.","type":"mcq","options":[{"k":"A","t":"10:17"},{"k":"B","t":"10:18"},{"k":"C","t":"10:20"},{"k":"D","t":"10:19"}],"answer":"D"},{"id":"fs-v1-1-1","topic":"rc","type":"mcq","passage":"fs-v1-p1","difficulty":"medium","src":"final","stem":"The author's main argument is that nudges","options":[{"k":"A","t":"are effective but modest, and should not replace policies that change underlying conditions"},{"k":"B","t":"were never effective and owe their reputation to selective publication"},{"k":"C","t":"should be preferred to taxes and subsidies because they cost almost nothing"},{"k":"D","t":"work only on irrational people and therefore have limited policy value"}],"answer":"A","explanation":"Paragraph 3 says the effects are ‘real; they were simply small’, and paragraph 4 warns against treating nudges as a ‘substitute for the expensive one’. The third option overstates (the author says effects are real); the fourth reverses the warning.\nPassage signal: medium — clear structure (claim, limits, arithmetic, verdict). A good second passage."},{"id":"fs-v1-1-2","topic":"rc","type":"mcq","passage":"fs-v1-p1","difficulty":"medium","src":"final","stem":"Which of the following, if true, would most weaken the author's claim about decisions ‘repeated daily’?","options":[{"k":"A","t":"Most published nudge studies measure outcomes within a month of the intervention"},{"k":"B","t":"A pension default raised enrolment among new employees but not among existing ones"},{"k":"C","t":"A one-time redesign of a cafeteria layout kept reducing sugary-drink purchases for three years"},{"k":"D","t":"People who opt out of a default usually have strong preferences about the decision"}],"answer":"C","explanation":"The author says nudges on repeated choices ‘fade’. A lasting effect on a daily, repeated choice (buying drinks) directly contradicts that. The third option, if anything, fits the author's suspicion; the second and fourth concern one-off decisions."},{"id":"fs-v1-1-3","topic":"rc","type":"mcq","passage":"fs-v1-p1","difficulty":"medium","src":"final","stem":"According to the passage, the gap between the academic literature and the nudge units' full set of trials is best explained by","options":[{"k":"A","t":"academic studies being run on decisions that people care about"},{"k":"B","t":"the nudge units testing weaker interventions than academic researchers did"},{"k":"C","t":"the nudge units deliberately understating their results"},{"k":"D","t":"the tendency to publish striking results and to report effects in proportional terms"}],"answer":"D","explanation":"Paragraph 3 names exactly two mechanisms: proportional reporting on low base rates and publication bias. The other options are not stated."},{"id":"fs-v1-1-4","topic":"rc","type":"mcq","passage":"fs-v1-p1","difficulty":"medium","src":"final","stem":"All of the following are consistent with the passage EXCEPT:","options":[{"k":"A","t":"A small effect at very low cost can be worthwhile."},{"k":"B","t":"Nudges are cheaper to introduce than taxes or subsidies."},{"k":"C","t":"A reminder may change behaviour only for a limited period."},{"k":"D","t":"Defaults have their strongest effect on decisions that people care most about."}],"answer":"D","explanation":"The passage says the opposite: ‘Defaults work best precisely where people care least.’ The other three are stated in paragraphs 1, 2 and 4.\nEXCEPT questions: check each option against one line of the passage; the one that reverses a line is the answer."},{"id":"fs-v1-2-1","topic":"rc","type":"mcq","passage":"fs-v1-p2","difficulty":"easy","src":"final","stem":"Why do marine biologists see the nodules differently from mining companies?","options":[{"k":"A","t":"Mining the nodules would release toxic metals into the water"},{"k":"B","t":"The nodules contain fewer valuable metals than companies claim"},{"k":"C","t":"The nodules are the only source of food in the deep sea"},{"k":"D","t":"The nodules provide the hard surface on which much of the deep-sea life depends"}],"answer":"D","explanation":"Paragraph 1: ‘the only hard surface … the anchor for most of the animals that live there’.\nPassage signal: easy — concrete science, plain vocabulary, detail questions. Do this one first."},{"id":"fs-v1-2-2","topic":"rc","type":"mcq","passage":"fs-v1-p2","difficulty":"easy","src":"final","stem":"The author mentions the test mining of the 1980s in order to","options":[{"k":"A","t":"suggest that scientists have studied the abyss for a long time"},{"k":"B","t":"argue that test mining should be banned"},{"k":"C","t":"show that the nodules grow back faster than expected"},{"k":"D","t":"show that damage to the deep seabed lasts for decades at least"}],"answer":"D","explanation":"The example supports the claim that habitat loss is ‘for practical purposes … permanent’."},{"id":"fs-v1-2-3","topic":"rc","type":"mcq","passage":"fs-v1-p2","difficulty":"easy","src":"final","stem":"Which of the following best describes the author's response to the supporters of seabed mining?","options":[{"k":"A","t":"It questions their assumption that future demand for these metals is certain"},{"k":"B","t":"It rejects their claim that mines on land cause harm"},{"k":"C","t":"It argues that no ecosystem should ever be damaged for metals"},{"k":"D","t":"It agrees that the deep sea is the least harmful source of metals"}],"answer":"A","explanation":"Paragraph 4: ‘it assumes that demand is fixed’, then cites new battery chemistries and recycling. The author calls their argument ‘serious’ and does not deny land-mining harms."},{"id":"fs-v1-2-4","topic":"rc","type":"mcq","passage":"fs-v1-p2","difficulty":"easy","src":"final","stem":"Which of the following can be inferred from the passage?","options":[{"k":"A","t":"A rise in battery recycling would weaken the case for seabed mining"},{"k":"B","t":"Most deep-sea species are found only on manganese nodules"},{"k":"C","t":"Mines on land cause less damage than mining on the seabed"},{"k":"D","t":"Electric vehicles can no longer be built without cobalt"}],"answer":"A","explanation":"Recycling reduces the need for new metal, which undercuts the demand forecast the miners rely on. The second option goes beyond the passage (most animals anchor on nodules; ‘found only on’ is not stated); the third contradicts paragraph 4."},{"id":"fs-v1-3-1","topic":"rc","type":"mcq","passage":"fs-v1-p3","difficulty":"hard","src":"final","stem":"The formalist view described in the passage holds that","options":[{"k":"A","t":"a painting's value should depend only on what can be seen in it"},{"k":"B","t":"critics are usually right about the beauty of paintings"},{"k":"C","t":"a forgery deserves more admiration than the original"},{"k":"D","t":"authorship is the main source of a painting's value"}],"answer":"A","explanation":"Paragraph 2: ‘what matters is what is visible on the canvas’.\nPassage signal: hard — abstract argument, a view described and then rebutted, careful wording in the options. Leave it for last unless the other passages are worse."},{"id":"fs-v1-3-2","topic":"rc","type":"mcq","passage":"fs-v1-p3","difficulty":"hard","src":"final","stem":"The author's main objection to the formalist view is that it","options":[{"k":"A","t":"cannot explain why experts were deceived by van Meegeren"},{"k":"B","t":"depends on the snobbery of critics"},{"k":"C","t":"ignores that a work of art is also an achievement relative to its historical circumstances"},{"k":"D","t":"treats forgers as more skilled than they are"}],"answer":"C","explanation":"Paragraph 3: ‘it is also an achievement, and achievements are relative to their circumstances.’ The last option is the formalist's charge against critics, not the author's objection to formalism."},{"id":"fs-v1-3-3","topic":"rc","type":"mcq","passage":"fs-v1-p3","difficulty":"hard","src":"final","stem":"Which of the following situations is most similar to the author's point about the two canvases?","options":[{"k":"A","t":"A copy of a painting that is labelled as a copy in a museum"},{"k":"B","t":"Two photographs of the same landscape taken on different days"},{"k":"C","t":"A translation of a novel that is more popular than the original"},{"k":"D","t":"A proof of an old theorem written today by a student who has read the original proof"}],"answer":"D","explanation":"The student's proof may look identical on the page, but it does not answer the same problem: the original solved something not yet known to be solvable. That matches ‘not answers to the same question’. The labelled copy makes no false claim about achievement, so it misses the point."},{"id":"fs-v1-3-4","topic":"rc","type":"mcq","passage":"fs-v1-p3","difficulty":"medium","src":"final","stem":"According to the author, the ‘scandal of a forgery’ lies in","options":[{"k":"A","t":"the fact that it is not beautiful once its origin is known"},{"k":"B","t":"a false answer to the question of what was achieved"},{"k":"C","t":"the poor technical quality of the forged work"},{"k":"D","t":"the damage it does to the reputation of the original artist"}],"answer":"B","explanation":"Last sentence: ‘The scandal of a forgery lies in having the second question answered falsely’ — the second question being ‘what has been done here?’"},{"id":"fs-v1-4-1","topic":"rc","type":"mcq","passage":"fs-v1-p4","difficulty":"medium","src":"final","stem":"According to the passage, why did port cities in the Indian Ocean become ‘places to wait’?","options":[{"k":"A","t":"Merchants needed time to obtain credit from local rulers"},{"k":"B","t":"Goods had to be stored until prices rose"},{"k":"C","t":"Ships could sail only in certain seasons, so traders who missed one had to stay until the next"},{"k":"D","t":"Portuguese forts forced ships to wait for passes"}],"answer":"C","explanation":"Paragraph 1 links the waiting to the monsoon timetable.\nPassage signal: medium — history with a clear argument; the last question asks for the main point."},{"id":"fs-v1-4-2","topic":"rc","type":"mcq","passage":"fs-v1-p4","difficulty":"medium","src":"final","stem":"The passage suggests that credit could travel between distant ports mainly because","options":[{"k":"A","t":"the Portuguese issued passes that guaranteed payment"},{"k":"B","t":"states enforced contracts across the ocean"},{"k":"C","t":"traders at both ends belonged to the same networks of kin and faith"},{"k":"D","t":"joint-stock companies financed the trade"}],"answer":"C","explanation":"Paragraph 2: ‘Trust, rather than any state, guaranteed the contracts.’"},{"id":"fs-v1-4-3","topic":"rc","type":"mcq","passage":"fs-v1-p4","difficulty":"medium","src":"final","stem":"The author's view of the Portuguese impact on Indian Ocean trade is that it was","options":[{"k":"A","t":"negligible, since they never built forts"},{"k":"B","t":"limited, since most trade stayed in Asian hands for two more centuries"},{"k":"C","t":"decisive, since they monopolised the pepper trade"},{"k":"D","t":"beneficial, since they unified local trades"}],"answer":"B","explanation":"‘Their success was partial.’ They did build forts and tried to monopolise pepper, so ‘negligible’ and ‘decisive’ both miss."},{"id":"fs-v1-4-4","topic":"rc","type":"mcq","passage":"fs-v1-p4","difficulty":"medium","src":"final","stem":"Which of the following best expresses the point of the last sentence of the passage?","options":[{"k":"A","t":"The monsoon world declined because it was primitive"},{"k":"B","t":"European cannons destroyed the Asian trading networks"},{"k":"C","t":"The joint-stock company, not armed attack, did more to transform the monsoon trade"},{"k":"D","t":"Systems of exchange always decline when they are attacked"}],"answer":"C","explanation":"The ‘force that most visibly attacks it’ is the Portuguese cannon; what displaced the system was the joint-stock company (paragraph 3). The second option contradicts paragraph 4."},{"id":"fs-v1-5","difficulty":"medium","src":"final","topic":"pj","type":"tita","sentences":["This is why confident eyewitnesses can be sincerely, and dangerously, wrong.","In the rebuilding, details from later experience, from conversation and even from suggestion can slip in.","Research over the past half-century suggests something quite different: each time we recall an event, we rebuild it from fragments.","Most people assume that a good memory works like a recording, storing events as they happened."],"stem":"The sentences below, when properly sequenced, form a coherent paragraph. Type the correct order of the sentence numbers.","answer":"4321","explanation":"(4) states the common assumption. (3) contradicts it (‘something quite different’). (2) explains what happens ‘in the rebuilding’ that (3) introduced. (1) draws the consequence (‘This is why’)."},{"id":"fs-v1-6","difficulty":"medium","src":"final","topic":"ooo","type":"tita","sentences":["Some city lizards have evolved stickier toe pads that help them cling to smooth walls and glass.","Rising rents in city centres have pushed many families into the suburbs.","Yet a growing number of species are not merely surviving in cities but adapting to them.","Urban birds in several countries now sing at a higher pitch, to be heard over traffic.","Cities have long been treated as the enemies of wildlife."],"stem":"Five sentences are given below. Four of them form a coherent paragraph. Type the number of the sentence that does not belong.","answer":"2","explanation":"(5)–(1) describe wildlife adapting to cities: the claim and two examples. (2) is about human housing costs — same setting, different subject."},{"id":"fs-v1-7","difficulty":"medium","src":"final","topic":"ps","type":"mcq","stem":"Read the paragraph and choose the option that best captures its essence.\n\nA language does not die when its last speaker dies; it dies when parents stop passing it to their children. By the time a language has only elderly speakers, its fate has usually been decided a generation earlier, in countless private decisions by families who judged that their children's prospects lay in another tongue. Efforts to revive such languages therefore succeed less through dictionaries and archives than through schools, media and economic incentives that make the language worth passing on.","options":[{"k":"A","t":"Languages die when their last speakers die, and archives can preserve them."},{"k":"B","t":"A language survives only if families pass it on, so revival must make the language worth passing on rather than merely record it."},{"k":"C","t":"Parents should be required to teach their children endangered languages."},{"k":"D","t":"Dictionaries and archives are useless for endangered languages."}],"answer":"B","explanation":"The paragraph moves from the real cause of language death (families stop passing it on) to what that means for revival. The fourth option turns ‘succeed less through’ into ‘useless’."},{"id":"fs-v1-8","difficulty":"medium","src":"final","topic":"sp","type":"mcq","stem":"There is a sentence that is missing in the paragraph below. Look at the paragraph and decide where (option 1, 2, 3 or 4) the sentence would best fit.\n\nSentence: Economists call this the rebound effect.\n\nParagraph: When a technology makes a resource cheaper to use, we expect consumption of that resource to fall. (1) More efficient engines, for example, should mean less fuel burned. (2) Often the opposite happens: cheaper running costs encourage people to drive more, or to buy larger cars, and total consumption rises. (3) It does not mean that efficiency is pointless, only that its benefits depend on what people do with the money and effort it frees. (4)","options":[{"k":"A","t":"Option 1"},{"k":"B","t":"Option 2"},{"k":"C","t":"Option 3"},{"k":"D","t":"Option 4"}],"answer":"C","explanation":"‘This’ needs the phenomenon just described — consumption rising despite efficiency — which is complete only at (3). The next sentence, ‘It does not mean…’, needs a named effect for ‘It’ to refer to. At (2) nothing has rebounded yet; at (4) ‘It’ would have no referent."},{"id":"fs-v1-9","difficulty":"hard","src":"final","topic":"pj","type":"tita","sentences":["Someone has to decide what to measure, how to measure it and what counts as an anomaly worth chasing.","The idea that scientists should ‘follow the data’ sounds unarguable.","Those decisions are shaped by theory, so the data a scientist follows are already partly of her own making.","But data do not arrive labelled with the questions they answer."],"stem":"The sentences below, when properly sequenced, form a coherent paragraph. Type the correct order of the sentence numbers.","answer":"2413","explanation":"(2) states a slogan. (4) challenges it (‘But’). (1) explains why data need decisions. (3) concludes that ‘those decisions’ (from (1)) are shaped by theory."},{"id":"fs-v1-10","difficulty":"hard","src":"final","topic":"ooo","type":"tita","sentences":["Translation has often been described as a betrayal of the original.","Every language divides the world differently, so no word carries exactly the same load in another tongue.","A translator must therefore choose what to sacrifice: rhythm, ambiguity, connotation or literal sense.","Machine translation now handles routine business correspondence with few errors.","Seen this way, translation is less a copy than a series of interpretive decisions."],"stem":"Five sentences are given below. Four of them form a coherent paragraph. Type the number of the sentence that does not belong.","answer":"4","explanation":"(1)–(5) argue that translation involves unavoidable choices: the old charge, the reason, the consequence and the reframing. (4) shifts to the accuracy of machine translation."},{"id":"fs-v1-11","difficulty":"hard","src":"final","topic":"ps","type":"mcq","stem":"Read the paragraph and choose the option that best captures its essence.\n\nMuseums like to describe their collections as belonging to humanity. The phrase is generous, but it can also be convenient. An object taken from a colony and displayed in a European capital may indeed be seen by more people there than at home; that does not settle who should decide its fate. To say that something belongs to everyone can be a way of saying that it belongs, in practice, to whoever already holds it.","options":[{"k":"A","t":"All museum collections were acquired unfairly."},{"k":"B","t":"Objects should be returned only if more people would see them at home."},{"k":"C","t":"Museums in Europe attract more visitors than those in former colonies."},{"k":"D","t":"Calling collections the property of humanity can hide the question of who controls them, which usually favours their current holders."}],"answer":"D","explanation":"The point is in the last sentence: talk of universal ownership can mask control by the holder. The second option is a supporting detail; the fourth overgeneralises."},{"id":"fs-v1-12","difficulty":"medium","src":"final","topic":"sp","type":"mcq","stem":"There is a sentence that is missing in the paragraph below. Look at the paragraph and decide where (option 1, 2, 3 or 4) the sentence would best fit.\n\nSentence: Ironically, the cure became part of the problem.\n\nParagraph: For decades, cities tried to ease traffic by building more roads. (1) New lanes did reduce congestion — for a while. (2) Then drivers who had avoided the road at peak hours returned, new housing grew up along the route, and the traffic came back. (3) Planners now speak of ‘induced demand’: extra capacity creates the traffic that fills it. (4) Some cities have begun to remove roads altogether and found, to their surprise, that traffic simply adjusts.","options":[{"k":"A","t":"Option 1"},{"k":"B","t":"Option 2"},{"k":"C","t":"Option 3"},{"k":"D","t":"Option 4"}],"answer":"C","explanation":"The sentence says the remedy (more roads) fed the problem. It fits at (3): after traffic comes back and before the planners' name for that effect. At (1) or (2) the cure has not yet failed."},{"id":"fs-v2-1-1","topic":"rc","type":"mcq","passage":"fs-v2-p1","difficulty":"medium","src":"final","stem":"The author's main concern in the passage is","options":[{"k":"A","t":"why newspaper editors should be treated as authors"},{"k":"B","t":"how text generators blur authorship, especially authorship as the expression of a particular mind"},{"k":"C","t":"whether large language models write better than people"},{"k":"D","t":"how copyright law should punish plagiarism by machines"}],"answer":"B","explanation":"Paragraph 1 states the problem; paragraph 4 says it is the ‘second meaning’ of authorship that is in doubt. The passage says the issue is ‘not because they write well’.\nPassage signal: medium — topical AI passage (AI appeared in both 2024 and 2025); the last paragraph is abstract."},{"id":"fs-v2-1-2","topic":"rc","type":"mcq","passage":"fs-v2-p1","difficulty":"medium","src":"final","stem":"The example of the report in the second paragraph is used to show that","options":[{"k":"A","t":"several parties have partial but incomplete claims to authorship"},{"k":"B","t":"language models produce most of the writing in offices"},{"k":"C","t":"prompts are the most creative part of writing with a model"},{"k":"D","t":"the person who revises a text is always its author"}],"answer":"A","explanation":"‘Each of the familiar candidates for authorship has a partial claim, and none has a complete one.’"},{"id":"fs-v2-1-3","topic":"rc","type":"mcq","passage":"fs-v2-p1","difficulty":"medium","src":"final","stem":"Which of the following, if true, would best support the author's argument in the final paragraph?","options":[{"k":"A","t":"Newspaper editors are often sued for headlines they did not write"},{"k":"B","t":"Language models are trained on texts written in many languages"},{"k":"C","t":"Readers who learn that a poem was machine-generated rate it lower even when they cannot tell the difference"},{"k":"D","t":"Most institutions now require staff to disclose their use of AI tools"}],"answer":"C","explanation":"This shows that people value authorship as a mind's effort and vision, separate from the text and from accountability. The second option is about disclosure rules, which the author says will not settle the issue; the third is about responsibility."},{"id":"fs-v2-1-4","topic":"rc","type":"mcq","passage":"fs-v2-p1","difficulty":"medium","src":"final","stem":"All of the following are stated or implied in the passage EXCEPT:","options":[{"k":"A","t":"The writers of a model's training texts are usually not credited."},{"k":"B","t":"Rules about disclosure may not resolve the question of authorship."},{"k":"C","t":"Holding someone responsible for a text is the same as calling them its author."},{"k":"D","t":"Copyright law assumes that a text comes from an identifiable person."}],"answer":"C","explanation":"Paragraph 4 opens: ‘responsibility and authorship have never been quite the same thing.’ The other three are stated in paragraphs 1, 2 and 4."},{"id":"fs-v2-2-1","topic":"rc","type":"mcq","passage":"fs-v2-p2","difficulty":"easy","src":"final","stem":"Which of the following is NOT given in the passage as a cause of the urban heat island?","options":[{"k":"A","t":"Air conditioners pushing heat into streets"},{"k":"B","t":"A lack of vegetation that cools the air"},{"k":"C","t":"Heat released at night by asphalt and concrete"},{"k":"D","t":"Tall buildings blocking the wind"}],"answer":"D","explanation":"Paragraph 1 lists the other three. Wind is never mentioned.\nPassage signal: easy — science-and-policy passage with concrete details. Do it first."},{"id":"fs-v2-2-2","topic":"rc","type":"mcq","passage":"fs-v2-p2","difficulty":"easy","src":"final","stem":"The passage suggests that poorer districts suffer more during heatwaves because","options":[{"k":"A","t":"they tend to be hotter and their residents are less able to protect themselves from heat"},{"k":"B","t":"they are further from the city centre"},{"k":"C","t":"their residents refuse to use air conditioning"},{"k":"D","t":"they have more trees, which use up water"}],"answer":"A","explanation":"Paragraph 2: hotter districts are often poorer, and their residents are less likely to have air conditioning and more likely to work outdoors."},{"id":"fs-v2-2-3","topic":"rc","type":"mcq","passage":"fs-v2-p2","difficulty":"easy","src":"final","stem":"The author's criticism of how cities treat trees is that they","options":[{"k":"A","t":"spend too much on maintaining old trees"},{"k":"B","t":"plant trees that are unsuited to the climate"},{"k":"C","t":"plant too many trees in wealthy areas"},{"k":"D","t":"regard trees as optional decoration rather than essential services"}],"answer":"D","explanation":"Paragraph 3: ‘cities often treat trees as decoration’."},{"id":"fs-v2-2-4","topic":"rc","type":"mcq","passage":"fs-v2-p2","difficulty":"easy","src":"final","stem":"Why, according to the passage, are the benefits of trees ‘easily ignored in annual budgets’?","options":[{"k":"A","t":"Trees are more expensive to plant than drains"},{"k":"B","t":"Annual budgets do not include public-health spending"},{"k":"C","t":"The costs come at once while the benefits build up over decades"},{"k":"D","t":"The benefits of trees cannot be measured"}],"answer":"C","explanation":"Paragraph 4: ‘A tree costs little to plant but takes decades to reach full size, so the benefits arrive slowly’."},{"id":"fs-v2-3-1","topic":"rc","type":"mcq","passage":"fs-v2-p3","difficulty":"hard","src":"final","stem":"According to the passage, returning a gift at once with something of equal value would be insulting because it","options":[{"k":"A","t":"breaks the rules of market exchange"},{"k":"B","t":"signals a wish to end the relationship of mutual obligation"},{"k":"C","t":"shows that the receiver is poorer than the giver"},{"k":"D","t":"makes the original gift seem worthless"}],"answer":"B","explanation":"Paragraph 1: it ‘would turn a relationship into a transaction and announce that the parties wished to owe each other nothing.’\nPassage signal: hard — anthropology, a contrast built up and then taken apart, an abstract conclusion."},{"id":"fs-v2-3-2","topic":"rc","type":"mcq","passage":"fs-v2-p3","difficulty":"hard","src":"final","stem":"The author mentions rivals who ‘ruined themselves to give away more’ in order to","options":[{"k":"A","t":"prove that gift economies were less efficient than markets"},{"k":"B","t":"argue that rivalry is natural in all societies"},{"k":"C","t":"illustrate the generosity of communal societies"},{"k":"D","t":"show that gift economies could be competitive and burdensome rather than simply warm"}],"answer":"D","explanation":"It is evidence against the romantic picture in paragraph 2."},{"id":"fs-v2-3-3","topic":"rc","type":"mcq","passage":"fs-v2-p3","difficulty":"hard","src":"final","stem":"Which of the following would the author most likely agree with?","options":[{"k":"A","t":"Markets work only between strangers"},{"k":"B","t":"A shopkeeper who gives a regular customer an unasked-for discount is keeping a relationship open"},{"k":"C","t":"Modern societies have lost the logic of the gift completely"},{"k":"D","t":"Gift economies were free of hierarchy"}],"answer":"B","explanation":"Paragraph 3: traders ‘give small gifts to keep a relationship alive’; paragraph 4 calls this the logic of keeping accounts open. The other options are views the author rejects."},{"id":"fs-v2-3-4","topic":"rc","type":"mcq","passage":"fs-v2-p3","difficulty":"medium","src":"final","stem":"The ‘contrast’ that the author calls ‘too neat’ is between","options":[{"k":"A","t":"communal societies bound by gift debts and individualist societies based on markets"},{"k":"B","t":"competitive and generous gift-givers"},{"k":"C","t":"rich and poor members of a gift economy"},{"k":"D","t":"anthropologists and economists"}],"answer":"A","explanation":"The contrast is drawn in paragraph 2 and rejected at the start of paragraph 3."},{"id":"fs-v2-4-1","topic":"rc","type":"mcq","passage":"fs-v2-p4","difficulty":"medium","src":"final","stem":"According to the passage, children do not adopt the accents of television presenters mainly because","options":[{"k":"A","t":"children watch too little television"},{"k":"B","t":"presenters speak with stigmatised accents"},{"k":"C","t":"they learn speech chiefly from people they interact with"},{"k":"D","t":"accents are inherited"}],"answer":"C","explanation":"Paragraph 1: ‘we learn to speak mainly from people we interact with, not from voices we merely hear.’\nPassage signal: medium — familiar topic, but the questions test the difference between exposure and influence."},{"id":"fs-v2-4-2","topic":"rc","type":"mcq","passage":"fs-v2-p4","difficulty":"medium","src":"final","stem":"The behaviour of teenagers described in the second paragraph suggests that accents","options":[{"k":"A","t":"become weaker during adolescence"},{"k":"B","t":"are learned mostly in classrooms"},{"k":"C","t":"are judged harshly only by older people"},{"k":"D","t":"can be used to signal both belonging and separation"}],"answer":"D","explanation":"Teenagers exaggerate local features ‘to mark themselves off from both their parents and the standard of the classroom’."},{"id":"fs-v2-4-3","topic":"rc","type":"mcq","passage":"fs-v2-p4","difficulty":"medium","src":"final","stem":"Which of the following is NOT supported by the passage?","options":[{"k":"A","t":"Accents can lead listeners to make unfair judgements about speakers."},{"k":"B","t":"Changes in accent usually start with national broadcasters and then spread to cities."},{"k":"C","t":"Young people play a large role in spreading new features of speech."},{"k":"D","t":"Some changes in accent spread quickly across large areas."}],"answer":"B","explanation":"Paragraph 3: changes move through networks ‘rather than descending from broadcasters’. The other three are stated."},{"id":"fs-v2-4-4","topic":"rc","type":"mcq","passage":"fs-v2-p4","difficulty":"medium","src":"final","stem":"The final sentence, ‘Exposure is not the same as influence’, most nearly means that","options":[{"k":"A","t":"influence on speech comes only from parents"},{"k":"B","t":"hearing a way of speaking does not make us adopt it unless we interact with its speakers"},{"k":"C","t":"people avoid hearing accents different from their own"},{"k":"D","t":"the media have no influence on culture"}],"answer":"B","explanation":"The paragraph grants that media spread words and fashions, so ‘no influence’ is too strong; the point is about the deeper patterns of speech."},{"id":"fs-v2-5","difficulty":"medium","src":"final","topic":"pj","type":"tita","sentences":["Their purpose was to show the order of the world as their makers understood it, not to help a traveller find a road.","Many placed a holy city at the centre and filled the margins with monsters and marvels.","Early maps were not meant to be accurate in the modern sense.","Judged by that purpose, they were not failed attempts at precision but successful pictures of a belief."],"stem":"The sentences below, when properly sequenced, form a coherent paragraph. Type the correct order of the sentence numbers.","answer":"3214","explanation":"(3) makes the claim. (2) gives features that show it. (1) states the real purpose (‘Their purpose’). (4) judges the maps ‘by that purpose’."},{"id":"fs-v2-6","difficulty":"medium","src":"final","topic":"ooo","type":"tita","sentences":["Many people now track their sleep using watches and phone applications.","Waste products that build up in the brain during waking hours are also cleared more quickly during sleep.","We now know that the sleeping brain is busy, replaying the day's experiences and strengthening some memories.","Seen in this light, cutting sleep short is not a saving of time but a cost to the brain's maintenance.","Sleep was once regarded as a period in which the brain simply switched off."],"stem":"Five sentences are given below. Four of them form a coherent paragraph. Type the number of the sentence that does not belong.","answer":"1","explanation":"(5)–(4): the old view, two things the sleeping brain does, and the conclusion. (1) is about sleep-tracking gadgets, which the paragraph never discusses."},{"id":"fs-v2-7","difficulty":"medium","src":"final","topic":"ps","type":"mcq","stem":"Read the paragraph and choose the option that best captures its essence.\n\nWe often praise people for ‘sticking to their principles’, as though changing one's mind were a sign of weakness. But a principle held regardless of evidence is not a virtue; it is a refusal to learn. The harder and more admirable thing is to hold views firmly enough to act on them and loosely enough to revise them when the facts change.","options":[{"k":"A","t":"Changing one's mind is always a sign of strength."},{"k":"B","t":"People should never stick to their principles."},{"k":"C","t":"Principles are less important than facts."},{"k":"D","t":"Holding views firmly enough to act on, yet being willing to revise them, is better than rigid consistency."}],"answer":"D","explanation":"The paragraph balances two demands: firmness to act and openness to revise. The second and third options are extremes the author does not take."},{"id":"fs-v2-8","difficulty":"medium","src":"final","topic":"sp","type":"mcq","stem":"There is a sentence that is missing in the paragraph below. Look at the paragraph and decide where (option 1, 2, 3 or 4) the sentence would best fit.\n\nSentence: That changed when reliable marine chronometers made it possible to know the home-port time while at sea.\n\nParagraph: For centuries sailors could find their latitude easily by measuring the height of the sun or the pole star. (1) Longitude was another matter. (2) Because the earth turns fifteen degrees an hour, a navigator who knew both local time and the time at his home port could calculate how far east or west he had travelled. (3) But pendulum clocks failed on a rolling ship, and errors of a few minutes meant errors of many kilometres. (4) Ships could at last be placed on the map with confidence, and fewer were wrecked on unexpected coasts.","options":[{"k":"A","t":"Option 1"},{"k":"B","t":"Option 2"},{"k":"C","t":"Option 3"},{"k":"D","t":"Option 4"}],"answer":"D","explanation":"‘That changed’ needs a problem just before it: the failure of clocks at sea, described in the sentence before (4). Then ‘Ships could at last…’ follows naturally."},{"id":"fs-v2-9","difficulty":"hard","src":"final","topic":"pj","type":"tita","sentences":["The distinction between weather and climate is simple to state.","To see a change in climate, one has to look past the noise of individual seasons to the trend beneath.","Weather is what happens on a given day; climate is the pattern of weather over decades.","This is why a single cold winter tells us almost nothing about whether the climate is warming."],"stem":"The sentences below, when properly sequenced, form a coherent paragraph. Type the correct order of the sentence numbers.","answer":"1342","explanation":"(1) introduces the distinction; (3) defines it; (4) draws a consequence (‘This is why’); (2) says what one must do instead."},{"id":"fs-v2-10","difficulty":"hard","src":"final","topic":"ooo","type":"tita","sentences":["Districts that stagnated for decades kept their old houses while booming areas rebuilt again and again.","When tastes later turned towards heritage, these neglected districts suddenly became the most desirable.","Preservation, in other words, is sometimes an accident of poverty rather than an act of care.","Modern architects increasingly use recycled materials in new buildings.","A city's oldest buildings often survive not because they were valued but because nobody could afford to replace them."],"stem":"Five sentences are given below. Four of them form a coherent paragraph. Type the number of the sentence that does not belong.","answer":"4","explanation":"(5)–(3) argue that old buildings often survived through neglect: claim, mechanism, later reversal, conclusion. (4) is about materials for new buildings."},{"id":"fs-v2-11","difficulty":"hard","src":"final","topic":"ps","type":"mcq","stem":"Read the paragraph and choose the option that best captures its essence.\n\nThe success of a scientific theory is often taken as evidence that it is true. Yet the history of science is crowded with theories that worked well for generations before being abandoned. This does not show that science is unreliable; it shows that predictive success and truth are different things, and that a theory may be useful long before — and long after — we have reason to believe it is literally correct.","options":[{"k":"A","t":"Scientific theories are usually false and therefore useless."},{"k":"B","t":"Successful theories are never abandoned."},{"k":"C","t":"Science is unreliable because theories change."},{"k":"D","t":"A theory's predictive success does not prove that it is true, though the theory may still be useful."}],"answer":"D","explanation":"The author separates success from truth and explicitly denies that science is unreliable. The second and fourth options are views the paragraph rejects."},{"id":"fs-v2-12","difficulty":"hard","src":"final","topic":"sp","type":"mcq","stem":"There is a sentence that is missing in the paragraph below. Look at the paragraph and decide where (option 1, 2, 3 or 4) the sentence would best fit.\n\nSentence: This is not a failure of memory but one of its functions.\n\nParagraph: We tend to think of forgetting as the enemy of learning. (1) Yet a mind that kept every detail would struggle to see patterns, because each experience would remain distinct from every other. (2) By letting go of particulars, memory extracts what is general: the rule rather than the instance, the face rather than the angle at which we saw it. (3) Forgetting, in short, is part of how we learn. (4) Some researchers now suggest that the ability to forget well may be as important as the ability to remember.","options":[{"k":"A","t":"Option 1"},{"k":"B","t":"Option 2"},{"k":"C","t":"Option 3"},{"k":"D","t":"Option 4"}],"answer":"C","explanation":"‘This’ must refer to letting go of particulars, described in the sentence just before (3). At (3) it bridges that description and the summary ‘Forgetting, in short, is part of how we learn.’"},{"id":"fs-v3-1-1","topic":"rc","type":"mcq","passage":"fs-v3-p1","difficulty":"medium","src":"final","stem":"According to the passage, the ‘harder cases’ are harder because","options":[{"k":"A","t":"the places of origin no longer exist"},{"k":"B","t":"museums have refused to research them"},{"k":"C","t":"the acquisitions were legal at the time but may not reflect real consent"},{"k":"D","t":"the objects are less valuable than those taken by soldiers"}],"answer":"C","explanation":"Paragraph 2 lists purchases under colonial rule, gifts from rulers ‘who may have had little choice’ and excavations the law allowed; paragraph 3 explains the clash between legality and consent.\nPassage signal: medium — law/culture topic close to the 2023 S3 museums passage. Two balanced arguments; read the options carefully."},{"id":"fs-v3-1-2","topic":"rc","type":"mcq","passage":"fs-v3-p1","difficulty":"medium","src":"final","stem":"The author's attitude towards the two arguments in the third paragraph is best described as","options":[{"k":"A","t":"favouring the argument against colonial law"},{"k":"B","t":"favouring the argument from the law of the time"},{"k":"C","t":"dismissing both as self-serving"},{"k":"D","t":"recognising that each has real force"}],"answer":"D","explanation":"‘Neither argument can be dismissed’, and the author states what each protects against."},{"id":"fs-v3-1-3","topic":"rc","type":"mcq","passage":"fs-v3-p1","difficulty":"medium","src":"final","stem":"Which of the following best captures the author's view of the emerging practice?","options":[{"k":"A","t":"It is a temporary arrangement until a principle is agreed"},{"k":"B","t":"It has satisfied both critics and museums"},{"k":"C","t":"It concedes too much to the countries of origin"},{"k":"D","t":"It may achieve more than a single rule by making museums know and state their objects' histories"}],"answer":"D","explanation":"Paragraph 4: ‘may achieve more than any single rule’. The second option is one group of critics' view, not the author's."},{"id":"fs-v3-1-4","topic":"rc","type":"mcq","passage":"fs-v3-p1","difficulty":"medium","src":"final","stem":"All of the following are mentioned in the passage as part of the emerging practice EXCEPT:","options":[{"k":"A","t":"Compensation paid to the countries of origin"},{"k":"B","t":"Joint exhibitions"},{"k":"C","t":"Shared research into provenance"},{"k":"D","t":"Long-term loans"}],"answer":"A","explanation":"Paragraph 4 lists negotiation, shared research, long-term loans and joint exhibitions. Compensation is never mentioned."},{"id":"fs-v3-2-1","topic":"rc","type":"mcq","passage":"fs-v3-p2","difficulty":"easy","src":"final","stem":"According to the passage, why does the octopus resemble ‘a committee’?","options":[{"k":"A","t":"Much of its nervous system is in its arms, which act with considerable independence"},{"k":"B","t":"Octopuses live and hunt in groups"},{"k":"C","t":"It learns by watching other octopuses"},{"k":"D","t":"Its brain is divided into eight separate parts"}],"answer":"A","explanation":"Paragraph 1: two-thirds of the neurons are in the arms, and each arm tastes, reaches and responds on its own.\nPassage signal: easy — popular science, detail questions. Do it first."},{"id":"fs-v3-2-2","topic":"rc","type":"mcq","passage":"fs-v3-p2","difficulty":"easy","src":"final","stem":"The author regards octopus intelligence as scientifically valuable mainly because it","options":[{"k":"A","t":"is greater than that of most mammals"},{"k":"B","t":"shows that intelligence evolved only once"},{"k":"C","t":"evolved independently of vertebrate intelligence and so offers a second case to compare"},{"k":"D","t":"proves that intelligence requires a skeleton"}],"answer":"C","explanation":"Paragraph 3: ‘The octopus offers a second experiment.’"},{"id":"fs-v3-2-3","topic":"rc","type":"mcq","passage":"fs-v3-p2","difficulty":"easy","src":"final","stem":"Which of the following can be inferred from the final paragraph?","options":[{"k":"A","t":"Short-lived animals cannot be intelligent"},{"k":"B","t":"Octopuses live longer than dogs"},{"k":"C","t":"Octopus mothers teach their young to open jars"},{"k":"D","t":"In humans, intelligence has often been explained by long lives and learning from others"}],"answer":"D","explanation":"‘the long lives and social learning that, in our own case, seemed to explain it’. The last option is the view the octopus case undercuts."},{"id":"fs-v3-2-4","topic":"rc","type":"mcq","passage":"fs-v3-p2","difficulty":"easy","src":"final","stem":"Which of the following is NOT mentioned as something octopuses can do?","options":[{"k":"A","t":"Recognise individual humans"},{"k":"B","t":"Use tools to build shelters"},{"k":"C","t":"Open jars"},{"k":"D","t":"Escape from tanks"}],"answer":"B","explanation":"Jars, tanks and telling humans apart are all in paragraphs 2–3. Tool use is not mentioned."},{"id":"fs-v3-3-1","topic":"rc","type":"mcq","passage":"fs-v3-p3","difficulty":"hard","src":"final","stem":"The author's main point in the passage is that","options":[{"k":"A","t":"since we cannot avoid relying on others, the real issue is how to judge whom to trust"},{"k":"B","t":"experts should be trusted without question"},{"k":"C","t":"independent thinking is the only path to real knowledge"},{"k":"D","t":"people who distrust experts have usually studied the subject"}],"answer":"A","explanation":"Paragraph 3: ‘The real question, then, is not whether to trust but whom, and on what grounds.’\nPassage signal: hard — philosophy of knowledge, an argument against an ideal, inference questions. Fair once you see the structure."},{"id":"fs-v3-3-2","topic":"rc","type":"mcq","passage":"fs-v3-p3","difficulty":"hard","src":"final","stem":"The author's attitude to the ideal of the independent thinker is that it is","options":[{"k":"A","t":"achievable for people with enough training"},{"k":"B","t":"useful as a warning against credulity but impossible if taken literally"},{"k":"C","t":"dangerous and should be abandoned"},{"k":"D","t":"the correct standard for all knowledge"}],"answer":"B","explanation":"Paragraph 2: ‘admirable as a corrective to credulity, but taken literally it is impossible.’"},{"id":"fs-v3-3-3","topic":"rc","type":"mcq","passage":"fs-v3-p3","difficulty":"hard","src":"final","stem":"Which of the following is NOT one of the indirect signs the author says a layperson can use to judge experts?","options":[{"k":"A","t":"Whether the expert can explain the claim in simple terms"},{"k":"B","t":"Whether the field has a record of reliable prediction"},{"k":"C","t":"Whether experts in the field largely agree"},{"k":"D","t":"Whether the expert gains from the claim"}],"answer":"A","explanation":"Paragraph 3 lists record of prediction, agreement, self-interest and staying within competence. Simplicity is not among them — tempting because it sounds sensible."},{"id":"fs-v3-3-4","topic":"rc","type":"mcq","passage":"fs-v3-p3","difficulty":"medium","src":"final","stem":"The author would most likely describe a person who rejects the vaccine consensus after reading an online forum as someone who has","options":[{"k":"A","t":"become an independent thinker"},{"k":"B","t":"studied immunology more carefully than experts"},{"k":"C","t":"transferred trust to a source supported by weaker signs"},{"k":"D","t":"stopped trusting anyone"}],"answer":"C","explanation":"Paragraph 4: distrust is ‘a shift of trust from one set of authorities to another’ resting on weaker signs."},{"id":"fs-v3-4-1","topic":"rc","type":"mcq","passage":"fs-v3-p4","difficulty":"medium","src":"final","stem":"The author uses the phrase ‘the menu of choices is written by someone else’ to suggest that","options":[{"k":"A","t":"platforms let workers set their own prices"},{"k":"B","t":"workers have no freedom at all"},{"k":"C","t":"workers' choices are real but limited by rules the platform controls"},{"k":"D","t":"workers prefer fixed hours"}],"answer":"C","explanation":"The paragraph shows choices shaped by hidden algorithms, pay changes and ratings; ‘The worker is free to choose’ rules out ‘no freedom at all’.\nPassage signal: medium — economics and law, clear structure, one question on a metaphor."},{"id":"fs-v3-4-2","topic":"rc","type":"mcq","passage":"fs-v3-p4","difficulty":"medium","src":"final","stem":"According to the passage, platform workers ‘fall awkwardly between’ two categories because they","options":[{"k":"A","t":"work for several platforms at once"},{"k":"B","t":"lack employees' protections and also lack the independence of a real business"},{"k":"C","t":"are directed by managers but bear their own risks"},{"k":"D","t":"earn more than employees but less than contractors"}],"answer":"B","explanation":"Paragraph 3, last sentence."},{"id":"fs-v3-4-3","topic":"rc","type":"mcq","passage":"fs-v3-p4","difficulty":"medium","src":"final","stem":"Which of the following is an objection to the intermediate category mentioned in the passage?","options":[{"k":"A","t":"It removes the minimum wage"},{"k":"B","t":"It gives platforms too little control over ratings"},{"k":"C","t":"It requires workers to keep fixed hours"},{"k":"D","t":"It may lock platform workers into a lower status"}],"answer":"D","explanation":"‘some unions argue that it entrenches a second-class status’. The category explicitly does not require fixed hours."},{"id":"fs-v3-4-4","topic":"rc","type":"mcq","passage":"fs-v3-p4","difficulty":"medium","src":"final","stem":"The last sentence of the passage implies that","options":[{"k":"A","t":"unions and platforms now agree on the solution"},{"k":"B","t":"the old legal categories of work may themselves need rethinking"},{"k":"C","t":"platform workers are adequately protected"},{"k":"D","t":"the gig economy should be banned"}],"answer":"B","explanation":"The gig economy has exposed ‘the age of the categories through which protection is offered.’"},{"id":"fs-v3-5","difficulty":"medium","src":"final","topic":"pj","type":"tita","sentences":["Eventually the artists and small businesses that started the change can no longer afford to stay.","Their arrival makes the area seem safer and more interesting to visitors.","In many cities, the first businesses to open in a run-down neighbourhood are cafés and galleries.","As visitors come, property values and rents begin to rise."],"stem":"The sentences below, when properly sequenced, form a coherent paragraph. Type the correct order of the sentence numbers.","answer":"3241","explanation":"A causal chain: (3) first arrivals → (2) the area seems attractive → (4) rents rise → (1) the pioneers are priced out (‘Eventually’)."},{"id":"fs-v3-6","difficulty":"medium","src":"final","topic":"ooo","type":"tita","sentences":["Handwritten manuscripts were often decorated with gold leaf and bright colours.","Printers needed consistent forms, and readers came to expect them.","Over time, spellings that had varied from town to town gave way to national norms.","The printing press made books cheaper and more widely available.","As more people read the same texts, spelling and grammar gradually became standardised."],"stem":"Five sentences are given below. Four of them form a coherent paragraph. Type the number of the sentence that does not belong.","answer":"1","explanation":"(4)–(3) trace how printing standardised language. (1) describes manuscript decoration, which plays no part in that argument."},{"id":"fs-v3-7","difficulty":"medium","src":"final","topic":"ps","type":"mcq","stem":"Read the paragraph and choose the option that best captures its essence.\n\nCities often measure success by growth: more residents, more jobs, more buildings. But growth can coexist with decline in the things that make a city worth living in — clean air, short commutes, affordable homes. A city that grows by pushing its poorer residents to ever more distant suburbs may look prosperous in the statistics while becoming harder to live in for most of its people.","options":[{"k":"A","t":"Cities should stop growing."},{"k":"B","t":"Suburbs are always worse places to live than city centres."},{"k":"C","t":"Statistics about cities are usually false."},{"k":"D","t":"Growth figures can hide a decline in how liveable a city is for most residents."}],"answer":"D","explanation":"The paragraph separates growth from liveability. It does not oppose growth itself or call statistics false."},{"id":"fs-v3-8","difficulty":"medium","src":"final","topic":"sp","type":"mcq","stem":"There is a sentence that is missing in the paragraph below. Look at the paragraph and decide where (option 1, 2, 3 or 4) the sentence would best fit.\n\nSentence: The difference lay not in the rules but in how they were enforced.\n\nParagraph: Two neighbouring towns passed almost identical laws against dumping waste in their rivers. (1) Ten years later, one river was clean and the other was as polluted as before. (2) In the first town, inspectors visited factories regularly and fines were collected. (3) In the second, inspections were rare and fines were routinely waived. (4) A law that is never applied, it turned out, is little better than no law.","options":[{"k":"A","t":"Option 1"},{"k":"B","t":"Option 2"},{"k":"C","t":"Option 3"},{"k":"D","t":"Option 4"}],"answer":"B","explanation":"The sentence explains the contrasting outcome just reported and introduces the two enforcement stories that follow. It belongs at (2), between the result and the details."},{"id":"fs-v3-9","difficulty":"hard","src":"final","topic":"pj","type":"tita","sentences":["Economists often assume that people know what they want.","Advertising, however, exists largely to shape preferences rather than to inform them.","If wants can be manufactured, the claim that markets serve people's wishes becomes harder to assess.","Their preferences are treated as given, and the task of the market is simply to satisfy them."],"stem":"The sentences below, when properly sequenced, form a coherent paragraph. Type the correct order of the sentence numbers.","answer":"1423","explanation":"(1) the assumption; (4) its consequence for markets; (2) the challenge (‘however’); (3) the implication for the claim in (4)."},{"id":"fs-v3-10","difficulty":"hard","src":"final","topic":"ooo","type":"tita","sentences":["Its value lies in choosing what matters for a particular purpose and ignoring the rest.","A good map leaves things out.","Theories in science work in much the same way, simplifying the world in order to explain it.","If it showed every tree and every stone, it would be as large and as useless as the land itself.","The oldest surviving maps were carved on clay tablets."],"stem":"Five sentences are given below. Four of them form a coherent paragraph. Type the number of the sentence that does not belong.","answer":"5","explanation":"(2)–(3) argue that maps (and theories) are useful because they simplify. (5) is a historical fact about early maps, unrelated to simplification."},{"id":"fs-v3-11","difficulty":"hard","src":"final","topic":"ps","type":"mcq","stem":"Read the paragraph and choose the option that best captures its essence.\n\nHistorians are fond of turning points — the battle, the invention, the speech after which nothing was the same. Such moments make good stories, but they can mislead. Most large changes are the result of slow shifts that had been under way for decades, and the famous event often marks the point at which a change became visible rather than the point at which it began.","options":[{"k":"A","t":"Famous turning points often mark when a long, gradual change became visible rather than when it began."},{"k":"B","t":"Historians should not write about battles or inventions."},{"k":"C","t":"Good stories are always inaccurate."},{"k":"D","t":"Large historical changes happen suddenly."}],"answer":"A","explanation":"The key sentence is the last one. The third option reverses it; the second and fourth overstate."},{"id":"fs-v3-12","difficulty":"hard","src":"final","topic":"sp","type":"mcq","stem":"There is a sentence that is missing in the paragraph below. Look at the paragraph and decide where (option 1, 2, 3 or 4) the sentence would best fit.\n\nSentence: The scarcity, in other words, was partly manufactured.\n\nParagraph: In the nineteenth century diamonds were rare, and their price reflected it. (1) Then huge deposits were found in southern Africa, and prices threatened to collapse. (2) A small group of companies responded by controlling supply, releasing only as many stones as the market could absorb at high prices. (3) Advertising later reinforced the idea that a diamond was a rare and permanent token of love. (4) The price of a diamond today owes as much to this history as to geology.","options":[{"k":"A","t":"Option 1"},{"k":"B","t":"Option 2"},{"k":"C","t":"Option 3"},{"k":"D","t":"Option 4"}],"answer":"C","explanation":"The sentence sums up what the companies did — restricting supply to keep diamonds scarce. It belongs at (3), right after that description and before advertising is added."},{"id":"fs-v4-1-1","topic":"rc","type":"mcq","passage":"fs-v4-p1","difficulty":"hard","src":"final","stem":"According to the passage, more recent critics differ from earlier ones in holding that","options":[{"k":"A","t":"the narrator's character can be diagnosed precisely"},{"k":"B","t":"unreliable narrators are always liars"},{"k":"C","t":"unreliability depends partly on the values of the reader"},{"k":"D","t":"authors never intend their narrators to be unreliable"}],"answer":"C","explanation":"Paragraph 2: ‘unreliability depends as much on the reader as on the narrator.’\nPassage signal: hard — literary theory, abstract, and the last paragraph qualifies what came before. Attempt it last."},{"id":"fs-v4-1-2","topic":"rc","type":"mcq","passage":"fs-v4-p1","difficulty":"hard","src":"final","stem":"The ‘uncomfortable consequence’ mentioned in the third paragraph is that","options":[{"k":"A","t":"readers stop trusting narrators altogether"},{"k":"B","t":"authors can no longer write unreliable narrators"},{"k":"C","t":"readers may mistake their own assumptions for the author's intention"},{"k":"D","t":"every reading of a text is equally valid"}],"answer":"C","explanation":"‘we have merely imported assumptions the author did not share.’ The third option is explicitly denied in paragraph 4."},{"id":"fs-v4-1-3","topic":"rc","type":"mcq","passage":"fs-v4-p1","difficulty":"hard","src":"final","stem":"The final sentence of the passage suggests that","options":[{"k":"A","t":"readers who believe they have exposed a narrator may themselves be in error"},{"k":"B","t":"authors deliberately deceive their readers"},{"k":"C","t":"narrators always see through their readers"},{"k":"D","t":"interpretation is a pleasure without risk"}],"answer":"A","explanation":"‘we are the ones who have been seen through’ — the reader's judgement may be the faulty one."},{"id":"fs-v4-1-4","topic":"rc","type":"mcq","passage":"fs-v4-p1","difficulty":"medium","src":"final","stem":"All of the following are consistent with the passage EXCEPT:","options":[{"k":"A","t":"Since unreliability depends on readers, no interpretation can be called better supported than another."},{"k":"B","t":"Readers usually begin by trusting a narrator."},{"k":"C","t":"Different generations may read the same narrator differently."},{"k":"D","t":"Contradictions and omissions can make readers suspect a narrator."}],"answer":"A","explanation":"Paragraph 4: ‘Some inferences are better supported than others.’ The other three come from paragraphs 1 and 2."},{"id":"fs-v4-2-1","topic":"rc","type":"mcq","passage":"fs-v4-p2","difficulty":"easy","src":"final","stem":"Before the railways, why did the differences in local time between towns ‘hardly matter’?","options":[{"k":"A","t":"Slow travel made a few minutes' difference insignificant"},{"k":"B","t":"All towns used the same time"},{"k":"C","t":"People rarely travelled between towns"},{"k":"D","t":"Clocks were too inaccurate to show the difference"}],"answer":"A","explanation":"Paragraph 1: ‘a journey of a day or two blurred a few minutes of local variation.’\nPassage signal: easy — narrative history with a clear lesson. Start here."},{"id":"fs-v4-2-2","topic":"rc","type":"mcq","passage":"fs-v4-p2","difficulty":"easy","src":"final","stem":"The passage mentions single-track lines in order to show that","options":[{"k":"A","t":"railways preferred to build single-track lines"},{"k":"B","t":"towns refused to change their clocks"},{"k":"C","t":"confusion over local times could lead to accidents"},{"k":"D","t":"trains ran more slowly than coaches"}],"answer":"C","explanation":"‘a misreading could put two trains on the same stretch at once.’"},{"id":"fs-v4-2-3","topic":"rc","type":"mcq","passage":"fs-v4-p2","difficulty":"easy","src":"final","stem":"Which of the following best describes how attitudes to standard time changed, according to the passage?","options":[{"k":"A","t":"It was accepted only by railway companies"},{"k":"B","t":"Initial resistance gave way to acceptance until it was no longer noticed"},{"k":"C","t":"It was welcomed at once by everyone"},{"k":"D","t":"It is still widely resisted today"}],"answer":"B","explanation":"Paragraph 3: resisted at first, then ‘its convenience soon made it invisible.’"},{"id":"fs-v4-2-4","topic":"rc","type":"mcq","passage":"fs-v4-p2","difficulty":"easy","src":"final","stem":"The main point of the last paragraph is that","options":[{"k":"A","t":"technologies always solve more problems than they create"},{"k":"B","t":"railways caused the differences in local time"},{"k":"C","t":"the sun's movement is a problem for travellers"},{"k":"D","t":"new technologies can turn long-standing facts into problems"}],"answer":"D","explanation":"‘The few minutes … had always existed. They became a problem only when trains moved fast enough.’"},{"id":"fs-v4-3-1","topic":"rc","type":"mcq","passage":"fs-v4-p3","difficulty":"medium","src":"final","stem":"According to the passage, why is storing water described as ‘a necessity’ in India?","options":[{"k":"A","t":"Dams prevent all floods"},{"k":"B","t":"Rivers in India flow only during the monsoon"},{"k":"C","t":"Cities have no other source of electricity"},{"k":"D","t":"Most rain falls in a few months, so water must be kept for the dry season"}],"answer":"D","explanation":"Paragraph 1, last sentence.\nPassage signal: medium — Indian policy passage (2025 S3 had two Indian passages). Balanced view, detail and inference questions."},{"id":"fs-v4-3-2","topic":"rc","type":"mcq","passage":"fs-v4-p3","difficulty":"medium","src":"final","stem":"Which of the following is NOT mentioned as a downstream effect of dams?","options":[{"k":"A","t":"Loss of seasonal floods that spread silt"},{"k":"B","t":"Decline of fisheries"},{"k":"C","t":"Shrinking deltas"},{"k":"D","t":"Increased salinity of groundwater in cities"}],"answer":"D","explanation":"Paragraph 2 lists the other three. Groundwater salinity is not mentioned."},{"id":"fs-v4-3-3","topic":"rc","type":"mcq","passage":"fs-v4-p3","difficulty":"medium","src":"final","stem":"The critics' main objection, as described in the third paragraph, is that","options":[{"k":"A","t":"dams have no benefits at all"},{"k":"B","t":"feasibility reports exaggerated costs"},{"k":"C","t":"the weighing of costs and benefits has been biased against people with little political voice"},{"k":"D","t":"irrigation is unnecessary in India"}],"answer":"C","explanation":"‘benefits were projected generously … costs, especially those borne by people with little political voice, were left out or discounted.’ The last option reverses this."},{"id":"fs-v4-3-4","topic":"rc","type":"mcq","passage":"fs-v4-p3","difficulty":"medium","src":"final","stem":"The idea of ‘environmental flows’ suggests that","options":[{"k":"A","t":"dams should release all their water every year"},{"k":"B","t":"rivers should be treated as pipes for moving water"},{"k":"C","t":"rivers should be managed so that they keep functioning as ecosystems"},{"k":"D","t":"no new dams should be built"}],"answer":"C","explanation":"‘releasing enough water to keep a river alive as a river’, contrasted with treating it ‘as a pipe’."},{"id":"fs-v4-4-1","topic":"rc","type":"mcq","passage":"fs-v4-p4","difficulty":"medium","src":"final","stem":"The ‘filing cabinet’ comparison in the first paragraph describes","options":[{"k":"A","t":"how rats store memories of fear"},{"k":"B","t":"the process of reconsolidation"},{"k":"C","t":"the current view that memories change each time they are recalled"},{"k":"D","t":"the older view that memories are stored permanently and unchanged by recall"}],"answer":"D","explanation":"Paragraph 1 describes the twentieth-century view; paragraph 2 challenges it.\nPassage signal: medium — science with one experiment to follow carefully."},{"id":"fs-v4-4-2","topic":"rc","type":"mcq","passage":"fs-v4-p4","difficulty":"medium","src":"final","stem":"In the experiment described, the rats showed less fear because","options":[{"k":"A","t":"the drug erased all their memories"},{"k":"B","t":"the memory had never been consolidated"},{"k":"C","t":"the tone was no longer paired with a shock during training"},{"k":"D","t":"the drug disrupted the re-storing of a memory that recall had made fragile"}],"answer":"D","explanation":"Paragraph 2: recall made the memory fragile, and the drug disrupted the restoring."},{"id":"fs-v4-4-3","topic":"rc","type":"mcq","passage":"fs-v4-p4","difficulty":"medium","src":"final","stem":"According to the passage, the ability of memories to change may be useful because","options":[{"k":"A","t":"it allows people to forget unpleasant events completely"},{"k":"B","t":"unchangeable memories would become less accurate as the world changed"},{"k":"C","t":"it makes memories stronger every time"},{"k":"D","t":"it prevents false memories"}],"answer":"B","explanation":"Paragraph 3: ‘a memory that could never change would become less accurate as the world changed around it.’ The last option is the opposite: drift helps explain false memories."},{"id":"fs-v4-4-4","topic":"rc","type":"mcq","passage":"fs-v4-p4","difficulty":"medium","src":"final","stem":"Which of the following best describes the author's view of the clinical use of reconsolidation?","options":[{"k":"A","t":"Entirely discredited"},{"k":"B","t":"Promising but not yet fully understood, with mixed results"},{"k":"C","t":"Completely successful in treating trauma"},{"k":"D","t":"Unrelated to the laboratory findings"}],"answer":"B","explanation":"Paragraph 4: hopes ‘partly realised’, ‘results have been mixed’, conditions ‘not fully understood’."},{"id":"fs-v4-5","difficulty":"medium","src":"final","topic":"pj","type":"tita","sentences":["Edward Jenner noticed that milkmaids who had caught cowpox seemed protected from smallpox.","The first vaccine was developed long before anyone understood how the immune system worked.","Only much later did scientists begin to explain why such protection worked.","He deliberately infected a boy with cowpox and later showed that the boy did not catch smallpox."],"stem":"The sentences below, when properly sequenced, form a coherent paragraph. Type the correct order of the sentence numbers.","answer":"2143","explanation":"(2) the general claim; (1) the observation; (4) the experiment that followed (‘He deliberately…’); (3) the later explanation (‘Only much later’)."},{"id":"fs-v4-6","difficulty":"medium","src":"final","topic":"ooo","type":"tita","sentences":["Without this transfer, many fruits and vegetables would produce far smaller harvests.","The decline of bee populations is therefore a concern for farmers as well as for conservationists.","As they move from flower to flower collecting nectar, they carry pollen between plants.","Bees are essential to the pollination of many crops.","Honey has been used as a sweetener for thousands of years."],"stem":"Five sentences are given below. Four of them form a coherent paragraph. Type the number of the sentence that does not belong.","answer":"5","explanation":"(4)–(2) build an argument about bees and pollination leading to a concern for farming. (5) is about honey as food, a different topic."},{"id":"fs-v4-7","difficulty":"medium","src":"final","topic":"ps","type":"mcq","stem":"Read the paragraph and choose the option that best captures its essence.\n\nMany people assume that the best way to learn a skill is to practise it until it feels easy. Research suggests otherwise. Practice that feels easy is often practice of what one can already do; real improvement tends to come from deliberately working on the parts that are still difficult, with feedback, even though such practice feels slower and less satisfying.","options":[{"k":"A","t":"Feedback makes practice more enjoyable."},{"k":"B","t":"Practice is less important than talent."},{"k":"C","t":"Improvement comes more from focused, uncomfortable practice on weaknesses than from easy repetition."},{"k":"D","t":"Skills should be practised only when they feel easy."}],"answer":"C","explanation":"The paragraph contrasts easy practice with deliberate work on difficulties. The third option reverses it."},{"id":"fs-v4-8","difficulty":"medium","src":"final","topic":"sp","type":"mcq","stem":"There is a sentence that is missing in the paragraph below. Look at the paragraph and decide where (option 1, 2, 3 or 4) the sentence would best fit.\n\nSentence: Ironically, the very success of antibiotics led to their misuse.\n\nParagraph: When antibiotics became widely available in the 1940s, infections that had killed millions became easy to cure. (1) Doctors prescribed them freely, farmers fed them to livestock, and patients often stopped taking them as soon as they felt better. (2) Each of these practices gave bacteria the chance to evolve resistance. (3) Today, some infections no longer respond to any of the drugs that once cured them. (4) New antibiotics are being developed, but far more slowly than resistance spreads.","options":[{"k":"A","t":"Option 1"},{"k":"B","t":"Option 2"},{"k":"C","t":"Option 3"},{"k":"D","t":"Option 4"}],"answer":"A","explanation":"The sentence links the triumph (first sentence) to the misuse listed next. At (1) it introduces that list; at later positions the misuse has already been described."},{"id":"fs-v4-9","difficulty":"hard","src":"final","topic":"pj","type":"tita","sentences":["Such monuments usually honour sacrifice and say little about the causes of the war or its costs to others.","A nation that remembers only its own sacrifice may find it harder to understand its former enemies.","Over time, the memory they preserve can become simpler and more heroic than the events themselves.","Societies tend to remember their wars through monuments to the dead."],"stem":"The sentences below, when properly sequenced, form a coherent paragraph. Type the correct order of the sentence numbers.","answer":"4132","explanation":"(4) the practice; (1) what such monuments say and leave out; (3) the effect over time; (2) the consequence for understanding others."},{"id":"fs-v4-10","difficulty":"hard","src":"final","topic":"ooo","type":"tita","sentences":["It also complicates the old question of how credit for a discovery should be divided.","Many papers now list dozens or even hundreds of authors from different institutions.","This reflects the scale of modern research, which often needs expensive equipment and many kinds of expertise.","The Nobel Prize in physics was first awarded in 1901.","Scientists rarely work alone any more."],"stem":"Five sentences are given below. Four of them form a coherent paragraph. Type the number of the sentence that does not belong.","answer":"4","explanation":"(5)–(1) discuss the rise of large research teams and its effect on credit. (4) is a historical fact about the Nobel Prize that the paragraph does not use."},{"id":"fs-v4-11","difficulty":"hard","src":"final","topic":"ps","type":"mcq","stem":"Read the paragraph and choose the option that best captures its essence.\n\nA rule that is clear but sometimes unjust may be better than one that is just but vague. Clear rules let people plan their lives and limit the discretion of officials, who might otherwise apply vague standards unevenly. Yet a clear rule applied mechanically to a case its makers never imagined can produce absurd results. Legal systems therefore keep trying to combine the predictability of rules with the flexibility of judgement.","options":[{"k":"A","t":"Legal systems try to balance the predictability of clear rules with the flexibility to avoid unjust outcomes."},{"k":"B","t":"Officials should have unlimited discretion."},{"k":"C","t":"Clear rules are always better than vague ones."},{"k":"D","t":"Vague rules prevent absurd results."}],"answer":"A","explanation":"The paragraph weighs clarity against flexibility and ends with the attempt to combine them. The second option ignores the ‘Yet’."},{"id":"fs-v4-12","difficulty":"hard","src":"final","topic":"sp","type":"mcq","stem":"There is a sentence that is missing in the paragraph below. Look at the paragraph and decide where (option 1, 2, 3 or 4) the sentence would best fit.\n\nSentence: The answer turned out to lie not in the plants but in the soil.\n\nParagraph: For years, farmers in the region puzzled over why the same variety of rice grew well in some fields and poorly in others nearby. (1) They tried different seeds, planting dates and amounts of fertiliser, with little effect. (2) Tests eventually showed that the poorer fields lacked a trace element, zinc, that the rice needed in tiny amounts. (3) Adding a small quantity of zinc to those fields raised yields dramatically. (4) The episode showed how a problem can resist solution when people look for it in the wrong place.","options":[{"k":"A","t":"Option 1"},{"k":"B","t":"Option 2"},{"k":"C","t":"Option 3"},{"k":"D","t":"Option 4"}],"answer":"B","explanation":"The sentence announces the answer after the failed attempts (seeds, dates, fertiliser — all about the plants) and before the soil tests that explain it: position (2)."}],"topics":[["sp","Sentence Placement","VARC"]]};
